def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(fn):
        cache = {}
        usage_order = []  # store keys by recency; most recent at the end

        def _make_key(args, kwargs, typed):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for k, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            now = timer()

            # If key is cached and not expired, return cached value
            if key in cache:
                res, expires = cache[key]
                if now < expires:
                    # Move key to the end to mark it as recently used
                    try:
                        usage_order.remove(key)
                    except ValueError:
                        pass
                    usage_order.append(key)
                    return res
                else:
                    # Expired entry; remove it
                    del cache[key]
                    try:
                        usage_order.remove(key)
                    except ValueError:
                        pass

            # Compute result and cache it
            result = fn(*args, **kwargs)
            expires = now + ttl
            cache[key] = (result, expires)
            usage_order.append(key)

            # Ensure the cache does not exceed maxsize
            if len(cache) > maxsize:
                oldest = usage_order.pop(0)
                del cache[oldest]

            return result

        return wrapper
    return decorator<|return|>

