def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise TypeError("maxsize must be a non-negative integer")
    if maxsize == 0:
        # No caching; return the original function
        def wrapper(func):
            cache_info = None
            def dummy(*args, **kwargs):
                return func(*args, **kwargs)
            dummy.cache_info = lambda: cache_info
            dummy.cache_clear = lambda: None
            dummy.__wrapped__ = func
            return dummy
        return wrapper

    def decorator(func):
        cache = {}
        counts = {}
        hits = misses = 0

        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types of arguments
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for k, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs)
            if key in cache:
                hits += 1
                counts[key] += 1
                return cache[key]
            misses += 1
            result = func(*args, **kwargs)
            cache[key] = result
            counts[key] = 1
            # Evict if necessary
            while len(cache) > maxsize:
                # Find key(s) with minimum usage count
                min_count = min(counts.values())
                # Evict one of the keys with min_count
                for evict_key in list(counts):
                    if counts[evict_key] == min_count:
                        del cache[evict_key]
                        del counts[evict_key]
                        break
            return result

        def cache_info():
            NonInteractiveInfo = lambda hits, misses, maxsize, currsize: \
                type('CacheInfo', (), {
                    "hits": hits,
                    "misses": misses,
                    "maxsize": maxsize,
                    "currsize": currsize
                })
            return NonInteractiveInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            counts.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.__wrapped__ = func
        return wrapper

    return decorator
