@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import os
    import traceback

    def _shorten_path(path, max_level):
        parts = path.split(os.sep)
        if len(parts) > max_level:
            return os.sep.join(['...' , *parts[-max_level:]])
        return path

    def _format_exc(exc):
        parts = []

        tb = exc.__traceback__
        if tb:
            extracted = traceback.extract_tb(tb, limit=max_level)
            for frame in extracted:
                file = _shorten_path(frame.filename, max_path_level)
                line = f'  File "{file}", line {frame.lineno}, in {frame.name}'
                parts.append(line)
                if frame.line:
                    parts.append(f'    {frame.line.strip()}')

        parts.append(f'{exc.__class__.__name__}: {exc}')
        return "\n".join(parts)

    # Build the string, including nested causes or contexts
    result_parts = [_format_exc(e)]
    cur_exc = e
    while True:
        cause = getattr(cur_exc, "__cause__", None)
        if cause is None:
            context = getattr(cur_exc, "__context__", None)
            # Only follow context if no explicit cause and the context was triggered by exception
            if context is None or not getattr(cur_exc, "__suppress_context__", False):
                cause = context
        if isinstance(cause, Exception):
            result_parts.append("Caused by:")
            result_parts.append(_format_exc(cause))
            cur_exc = cause
        else:
            break

    return "\n".join(result_parts)<|return|>

