def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    kept = []
    for c in reversed(classes):
        # skip if any already kept class is subclass of c
        if any(issubclass(kept_c, c) for kept_c in kept):
            continue
        kept.append(c)
    return list(reversed(kept))<|return|>

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for c in classes:
        # Skip non‑class objects
        if not isinstance(c, type):
            continue
        # Avoid duplicates
        if c in minimal:
            continue
        # Drop c if some other class in the list is a subclass of it
        redundant = False
        for d in classes:
            if d is c:
                continue
            if not isinstance(d, type):
                continue
            try:
                if issubclass(d, c):
                    redundant = True
                    break
            except TypeError:
                continue
        if not redundant:
            minimal.append(c)
    return minimal<|return|>

