def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.
    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Treat single non-iterable items as a lone element
    try:
        _ = iter(sequence)
    except TypeError:
        output.append(sequence)
        return output

    # Flatten nested tuples/lists (but keep simple interfaces unchanged)
    for item in sequence:
        if (
            isinstance(item, (list, tuple))
            and not isinstance(item, (str, bytes))
        ):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output<|return|>

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        # Skip None values
        if item is None:
            continue

        # Treat all non-string iterables (like list, tuple) as nested
        if isinstance(item, (list, tuple, set)):
            _normalizeargs(item, output)
        # If the item has an 'interface' attribute (Declarion), use it
        elif hasattr(item, "interface"):
            output.append(item.interface)
        # If the item itself contains 'interfaces' attribute, extend it
        elif hasattr(item, "interfaces"):
            interfaces = getattr(item, "interfaces")
            if isinstance(interfaces, (list, tuple, set)):
                output.extend(interfaces)
            else:
                output.append(interfaces)
        # For every other object assume it's an individual interface
        else:
            output.append(item)

    return output<|return|>

