def to_csv(self, separator=",", header=None):
        """Convert graph's points to CSV."""
        # Prepare list of lines
        lines = []

        # Add optional header
        if header is not None:
            lines.append(header)

        # Determine iterable of (coord, value) pairs
        # Prefer graph.points if exists, else items, else directly iterable
        try:
            items = self.points.items()
        except AttributeError:
            try:
                items = self.items()
            except AttributeError:
                items = self  # assume iterable of tuples

        for coord, value in items:
            # Convert coordinate(s) to string
            if isinstance(coord, (list, tuple)):
                coord_parts = [str(c) for c in coord]
            else:
                coord_parts = [str(coord)]

            # Convert value(s) to string
            if isinstance(value, (list, tuple)):
                value_parts = [str(v) for v in value]
            else:
                value_parts = [str(value)]

            # Join parts with separator and add to lines
            line = separator.join(coord_parts + value_parts)
            lines.append(line)

        # If nothing was added besides header, return header or empty string
        if not lines and header is None:
            return ""
        return "\n".join(lines)<|return|>

def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to a CSV string.

        Parameters
        ----------
        separator : str, optional
            Delimiter used between fields. Defaults to ','.
        header : str or None, optional
            If provided, the header string is added as the first line.

        Returns
        -------
        str
            The CSV representation.
        """
        lines = []

        # Add header if requested.
        if header is not None:
            lines.append(str(header))

        # Determine how points are stored. We try the most common patterns.
        iter_pts = None
        try:
            # Prefer a dedicated iterator if available (e.g. as a method).
            if hasattr(self, "iterpoints") and callable(self.iterpoints):
                iter_pts = self.iterpoints()
        except Exception:
            pass

        if iter_pts is None:
            # Fallback to a points attribute or any iterable attribute.
            for attr in ("points", "data", "items"):
                if hasattr(self, attr):
                    iter_pts = getattr(self, attr)
                    break

        if iter_pts is None:
            raise ValueError("Unable to find points in graph for CSV conversion.")

        # Process each point.
        for pt in iter_pts:
            # Attempt the most common form: (coordinates, value)
            try:
                coords, val = pt
            except Exception:
                # Try attribute-based access.
                try:
                    if hasattr(pt, "coordinates") and hasattr(pt, "value"):
                        coords = pt.coordinates
                        val = pt.value
                    else:
                        # Fallback: treat the point itself as the coordinate
                        # and set value to None.
                        coords = pt
                        val = None
                except Exception:
                    coords = pt
                    val = None

            # Normalize coordinates to an iterable.
            if isinstance(coords, (str, bytes)):
                coord_parts = [str(coords)]
            else:
                try:
                    coord_parts = [str(c) for c in coords]
                except Exception:
                    coord_parts = [str(coords)]

            # Normalize value to parts.
            if val is None:
                val_parts = []
            elif isinstance(val, (str, bytes)):
                val_parts = [str(val)]
            else:
                try:
                    val_parts = [str(v) for v in val]
                except Exception:
                    val_parts = [str(val)]

            # Build the line.
            line = separator.join(coord_parts + val_parts)
            lines.append(line)

        return "\n".join(lines)<|return|>

