def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If the sequence itself is a Source, deny immediately.
    try:
        if isinstance(seq, Source):  # type available in calling context
            return False
    except NameError:
        # Source class not defined; ignore this check
        pass

    # If the object is already a FillRequest, it's trivially a sequence
    try:
        if isinstance(seq, FillRequest):  # type available in calling context
            return True
    except NameError:
        # FillRequest class not defined; proceed with duck-check below
        pass

    # Treat any non-string iterable as a candidate sequence
    from collections.abc import Iterable
    if isinstance(seq, str):
        return False  # strings are iterable but not valid sequences here
    if not isinstance(seq, Iterable):
        return False

    # Check each element for being a FillRequest
    for elem in seq:
        try:
            if isinstance(elem, FillRequest):
                return True
        except NameError:
            # If the class isn't defined yet, we can't perform a direct isinstance check.
            # Fall back to duck typing – look for key attributes typical of a FillRequest.
            # This is a best-effort approach; if the element has a 'request_id' and 'symbol',
            # we consider it a FillRequest.
