def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure *coord* is an array-like of the correct dimension.
    try:
        coord_arr = np.asarray(coord)
    except Exception:
        return
    # Handle the case of single dimension histograms where *coord* might be a scalar.
    ndim = len(self.edges) if isinstance(self.edges, (list, tuple)) else 1
    if ndim == 1:
        if np.isscalar(coord):
            coord_arr = np.array([coord])
        if coord_arr.shape != (1,):
            return
    else:
        if coord_arr.shape != (ndim,):
            return
    # Find the bin index for each dimension.
    indices = []
    for c, edge in zip(coord_arr.flat, self.edges):
        # Find rightmost insertion position; subtract one to get bin index.
        idx = np.searchsorted(edge, c, side="right") - 1
        # If coordinate is outside the range, ignore the fill request.
        if idx < 0 or idx >= len(edge) - 1:
            return
        indices.append(idx)
    # Increment the histogram bin by the given weight.
    self.hist[tuple(indices)] += weight<|return|>

