def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Create a default observer schema dictionary based on a portion of a Kubernetes
    resource manifest.  All non-list and non-dict leaf values are replaced by ``None``.
    When *first_level* is ``True`` the dictionary represents a complete observer
    schema for a resource, so the values of the identifying fields ('kind',
    'apiVersion', and 'metadata') are copied directly from the manifest.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    # Keys that identify a Kubernetes resource
    IDENTIFYING_KEYS = {"kind", "apiVersion", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        # Handle dictionaries (recursively) except for identifying keys at the top level
        if isinstance(value, dict):
            if first_level and key in IDENTIFYING_KEYS:
                # Copy the whole identifying dict/value unchanged
                result[key] = value
            else:
                result[key] = generate_default_observer_schema_dict(value, False)
        # Handle lists – leave them unchanged
        elif isinstance(value, list):
            result[key] = value
        # Handle primitive values
        else:
            if first_level and key in IDENTIFYING_KEYS:
                # Preserve the identifying field value
                result[key] = value
            else:
                result[key] = None
    return result<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """

    identifying_fields = {"apiVersion", "kind", "metadata"}
    identifying_subfields = {"name", "namespace", "uid"}

    def process_list(items):
        new_list = []
        for item in items:
            if isinstance(item, dict):
                new_list.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                new_list.append(process_list(item))
            else:
                new_list.append(None)
        return new_list

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            if first_level and key in identifying_fields:
                if key == "metadata":
                    meta_copy = {}
                    for subkey, subvalue in value.items():
                        if subkey in identifying_subfields:
                            meta_copy[subkey] = subvalue
                        else:
                            meta_copy[subkey] = None
                    result[key] = meta_copy
                else:
                    result[key] = value  # copy verbatim for top-level identifying fields
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = process_list(value)
        else:
            if first_level and key in identifying_fields:
                result[key] = value
            else:
                result[key] = None
    return result
<|return|>

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Do nothing if the response is not a list
    if not isinstance(response, list):
        return

    # Determine the sub‑schema for items in the list.  The schema can be a
    # single element (for homogeneous lists) or a list of elements (rare but
    # supported for consistency).
    sub_schema = None
    if isinstance(observer_schema, list):
        if observer_schema:
            sub_schema = observer_schema[0]
    else:
        sub_schema = observer_schema

    # Iterate over the received items
    for idx, resp_item in enumerate(response):
        # Ensure the target list has a placeholder at the same index
        if idx >= len(last_applied_manifest) or last_applied_manifest[idx] is None:
            # No value yet: we need to create a placeholder
            if isinstance(resp_item, dict) and isinstance(sub_schema, dict):
                # Create a new dict containing only the keys we observe
                new_dict = {}
                for key in sub_schema:
                    if key in resp_item:
                        new_dict[key] = None
                last_applied_manifest.append(new_dict)
                # Recurse into the new dict to fill values
                update_last_applied_manifest_dict_from_resp(
                    new_dict, sub_schema, resp_item
                )
            elif isinstance(resp_item, list) and isinstance(sub_schema, list):
                # Create an empty list (same length as resp_item)
                new_list = [None] * len(resp_item)
                last_applied_manifest.append(new_list)
                # Recurse into the new list to fill values
                update_last_applied_manifest_list_from_resp(
                    new_list, sub_schema, resp_item
                )
            else:
                # Primitive value: set directly if we observe it
                # If the observer schema says we observe primitive values,
                # we set it; otherwise we skip.
                if sub_schema is None or sub_schema is True:
                    last_applied_manifest.append(resp_item)
                else:
                    # If sub_schema is False or empty, we still append None
                    last_applied_manifest.append(None)
        else:
            # Value already exists; only update nested structures if present
            target = last_applied_manifest[idx]
            if isinstance(resp_item, dict) and isinstance(
                target, dict
            ):
                update_last_applied_manifest_dict_from_resp(
                    target, sub_schema, resp_item
                )
            elif isinstance(resp_item, list) and isinstance(
                target, list
            ):
                update_last_applied_manifest_list_from_resp(
                    target, sub_schema, resp_item
                )
            else:
                # Primitive values are left untouched if already present
                pass

    # Remove any trailing None values that were added but never populated
    while last_applied_manifest and last_applied_manifest[-1] is None:
        last_applied_manifest.pop()<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Within a nested dictionary structure, populate any missing keys in
    *last_applied_manifest* using the values present in *response* as specified
    by *observer_schema*.  Keys that are already present in
    *last_applied_manifest* are left untouched.  The function raises
    :class:`KeyError` if any key that should be observed is not present
    in *response*.

    Parameters
    ----------
    last_applied_manifest : dict
        The partially completed manifest that will be updated in-place.
    observer_schema : dict
        A nested description of the fields that should be observed.
        Scalar fields are represented by any non-dict value (e.g. a
        string indicating the type).  Nested dictionaries are either
        dictionaries (representing nested objects) or a dictionary
        containing a ``"type"`` key whose value is ``"dict"`` or ``"list"``.
    response : dict
        The API response from which the values are to be copied.
    """
    for key, schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed key '{key}' missing from response")

        # Handle a schema that explicitly describes a dict or list type
        if isinstance(schema, dict) and "type" in schema:
            type_name = schema["type"]
            if type_name == "dict":
                sub_response = response[key]
                if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                    last_applied_manifest[key] = {}
                # For dict type, recurse with the nested properties
                nested_schema = schema.get("properties", {})
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], nested_schema, sub_response
                )
            elif type_name == "list":
                # Delegates to the list‑handling routine that must be defined elsewhere
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest, key, schema.get("items", {}), response[key]
                )
            else:
                # Treat as a scalar field
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = response[key]
        elif isinstance(schema, dict):
            # Implicit nested dictionary; recurse
            sub_response = response[key]
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, sub_response
            )
        else:
            # Primitive scalar field
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]
    return last_applied_manifest<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: A mapping from resource identifiers (typically the resource's name)
              to a default observer schema dictionary. Resources that already have
              a custom observer schema specified in ``app.spec.observers`` are
              omitted from the returned mapping.
    """
    # Guard against missing attributes
    try:
        manifest = app.spec.manifest
    except AttributeError:
        # If the application does not have a spec or manifest, return an empty
        # mapping.
        return {}

    # The `app.spec.observers` attribute (if present) is expected to hold
    # custom observer schemas, keyed by an identifier that matches the one
    # derived below.  It may be omitted or `None`, in which case we treat it
    # as an empty mapping.
    custom_observers = getattr(app.spec, "observers", {})
    if custom_observers is None:
        custom_observers = {}

    default_schemas = {}

    # The manifest could be a list of resource dictionaries or a dictionary
    # keyed by resource names.  Handle both cases.
    if isinstance(manifest, list):
        resources_iter = enumerate(manifest)
    elif isinstance(manifest, dict):
        resources_iter = manifest.items()
    else:
        # Unsupported manifest format – return empty mapping.
        return {}

    for key, resource in resources_iter:
        # Use the resource's name as the key when possible.  If the resource
        # definition does not contain a name, fall back to the numeric index
        # (for list manifests) or the dict key.
        if isinstance(key, int):
            identifier = f"resource-{key}"
        else:
            identifier = key

        # Try to derive a meaningful name from the resource metadata if it
        # exists – this is typically what a custom observer schema would use.
        res_name = None
        if isinstance(resource, dict):
            res_name = resource.get("metadata", {}).get("name")
        if res_name:
            identifier = res_name

        # Skip resources that already have a custom observer schema.
        if identifier in custom_observers:
            continue

        # Build a minimal default schema:
        #   * Keep the API version and kind from the resource.
        #   * Include the resource's name in the metadata block.
        default_schema = {}
        if isinstance(resource, dict):
            default_schema["apiVersion"] = resource.get("apiVersion", "")
            default_schema["kind"] = resource.get("kind", "")
            default_schema["metadata"] = {"name": res_name} if res_name else {}
        else:
            # When the resource is not a dict we cannot construct a schema.
            # Skip such entries.
            continue

        default_schemas[identifier] = default_schema

    return default_schemas<|return|>

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    # Helper to check existence on a pyfilesystem-like object
    def _pyfs_exists(fs, subpath):
        try:
            return fs.exists(subpath)
        except Exception:
            return False

    # Handle pyfs FS root
    if hasattr(path, "exists"):
        fs = path
        meta = os.path.join(".ocfl", "metadata.json")
        # The object is considered valid if the metadata file exists
        return _pyfs_exists(fs, meta)

    # Handle standard filesystem path
    # Normalize path to a string
    if hasattr(path, "__fspath__"):
        path = os.fspath(path)

    if not isinstance(path, str) or not os.path.isdir(path):
        return False

    meta_path = os.path.join(path, ".ocfl", "metadata.json")
    return os.path.isfile(meta_path)<|return|>

