def status_str(self, prefix=''):
    """
    Return string representation of validation log, with optional prefix.
    """
    # Determine which attribute holds the log
    if hasattr(self, 'validation_log'):
        log_data = self.validation_log
    elif hasattr(self, 'log'):
        log_data = self.log
    else:
        return ''
    # Convert to a list of lines if necessary
    if isinstance(log_data, str):
        lines = [log_data]
    else:
        try:
            lines = list(log_data)
