def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Determine the log structure: attempt to use a common attribute name
    log = getattr(self, 'log', None)
    if log is None:
        # Fallback to other possible names
        log = getattr(self, 'validation_log', None)
    if not log:
        return ''
    lines = []
    for entry in log:
        # If entry is a simple string, use it directly
        if isinstance(entry, str):
            lines.append(f"{prefix}{entry}")
        # If entry is a tuple/list with a kind and a message
        elif isinstance(entry, (tuple, list)) and len(entry) == 2:
            kind, msg = entry
            kind_str = str(kind).upper() if isinstance(kind, str) else str(kind)
            lines.append(f"{prefix}{kind_str}: {msg}")
        else:
            # Default fallback
            lines.append(f"{prefix}{str(entry)}")
    return "\n".join(lines)<|return|>

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to get the entries from a typical attribute
    entries = getattr(self, 'entries', None)
    if entries is None:
        entries = getattr(self, 'log', [])
    # Ensure we have an iterable
    if not isinstance(entries, (list, tuple)):
        try:
            entries = list(entries)
        except Exception:
            entries = [entries]
    if not entries:
        return f"{prefix}<no entries>"
    lines = []
    for entry in entries:
        if isinstance(entry, str):
            lines.append(f"{prefix}{entry}")
        else:
            try:
                entry_str = str(entry)
            except Exception:
                entry_str = repr(entry)
            lines.append(f"{prefix}{entry_str}")
    return "\n".join(lines)<|return|>

def status_str(self, prefix=''):
