def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to retrieve a log attribute; fall back to empty string if none exists.
    log = getattr(self, 'log', None) or getattr(self, 'validation_log', None)
    if not log:
        return ''
    # If the log is a single string, treat it as one line; otherwise convert all entries to strings.
    if isinstance(log, (str, bytes)):
        lines = [str(log)]
    else:
        lines = [str(item) for item in log]
    # Prepend the optional prefix to each line and join with newline characters.
    if prefix:
        lines = [f"{prefix}{line}" for line in lines]
    return "\n".join(lines)<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Basic required keys for an inventory
    required_keys = ["type", "name", "components", "metadata"]
    missing = [k for k in required_keys if k not in inventory]
    if missing:
        raise ValueError(f"Missing required keys in inventory: {missing}")

    if extract_spec_version:
        inv_type = inventory.get("type")
        if isinstance(inv_type, str):
            # Attempt to extract a version number (e.g., “spec-2.1”) from the type string
            import re

            match = re.search(r"(\\d+\\.\\d+)", inv_type)
            if match:
                self.spec_version = match.group(1)
    # Ensure we have a spec version to base further checks on
    if not getattr(self, "spec_version", None):
        raise ValueError("Specification version is unavailable")

    # Perform basic checks that differ by spec version
    if self.spec_version.startswith("2."):
        # In spec 2.x inventories must have a non-empty list of components
        comps = inventory.get("components")
        if not isinstance(comps, list) or not comps:
            raise ValueError("Components must be a non-empty list for spec 2.x inventories")

        # Metadata should contain a version field that matches the spec_version
        meta_ver = inventory["metadata"].get("version")
        if meta_ver != self.spec_version:
            raise ValueError(
                f"Metadata version '{meta_ver}' does not match inventory spec_version '{self.spec_version}'"
            )
    else:
        # For other spec versions, ensure 'metadata' contains a non-empty dict
        meta = inventory.get("metadata")
        if not isinstance(meta, dict) or not meta:
            raise ValueError("Metadata must be a non-empty dictionary for non-2.x specs")

    return True<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    # Extract spec_version from the type field if requested.
    if extract_spec_version:
        type_value = inventory.get("type")
        if isinstance(type_value, str):
            # Expect a format like "spec-<version>" or "inventory-<version>"
            parts = type_value.split("-", 1)
            if len(parts) == 2 and parts[1].isdigit():
                self.spec_version = parts[1]
            # If the type value doesn't match the expected pattern, leave spec_version unchanged
        else:
            # No or invalid type value; fall back to existing self.spec_version
            pass

    # Basic required field checks
    required = ("name", "type", "description")
    missing = [field for field in required if field not in inventory]
    if missing:
        raise ValueError(f"Inventory is missing required fields: {missing}")

    # Validate that spec_version is set when needed
    if not hasattr(self, "spec_version") or self.spec_version is None:
        raise ValueError("spec_version must be set either in self or inferred from type")

    # Additional simple checks (can be extended as needed)
    if not isinstance(inventory["name"], str) or not inventory["name"]:
        raise ValueError("Inventory 'name' must be a non-empty string")

    if not isinstance(inventory["type"], str) or not inventory["type"]:
        raise ValueError("Inventory 'type' must be a non-empty string")

    if not isinstance(inventory["description"], str):
        raise ValueError("Inventory 'description' must be a string")

    # Optional: validate elements list if present
    elements = inventory.get("elements")
    if elements is not None and not isinstance(elements, list):
        raise ValueError("Inventory 'elements' must be a list if provided")

    return True<|return|>

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checking
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        type_value = inventory.get("type")
        # Accept common spec identifiers; add more as needed
        if isinstance(type_value, str):
            type_lower = type_value.lower()
            if type_lower in {"ecs", "compose"}:
                spec_version = type_lower
            else:
                # If an unexpected type is provided, fall back to default
                spec_version = self.spec_version

    # Perform minimal validation based on the spec version
    if spec_version == "ecs":
        required_keys = {"ecs_service", "cluster"}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(f"Missing required ECS keys: {', '.join(missing)}")
    elif spec_version == "compose":
        if "services" not in inventory:
            raise ValueError("Missing 'services' section in Compose inventory")
        if not isinstance(inventory["services"], dict):
            raise ValueError("'services' must be a dictionary")
    else:
        # If the spec version is not recognized, raise an error
        raise ValueError(f"Unsupported specification version: {spec_version}")

    # If all checks pass, validation succeeded
    return spec_version  # Returning the determined spec_version can be useful for callers
<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Extract specification version from the 'type' field if requested
    if extract_spec_version:
        typ = inventory.get("type")
        extracted_version = None
        if isinstance(typ, str):
            # Try to locate a dotted number (e.g., "1.2" or "v1.2")
            parts = typ.replace(":", " ").replace(",", " ").split()
            for part in parts:
                if all(ch.isdigit() or ch == "." for ch in part):
                    extracted_version = part
                    break
        if extracted_version:
            self.spec_version = extracted_version

    # Validation rules
    required_keys = {"id", "label", "elements"}
    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"inventory is missing required keys: {', '.join(sorted(missing))}")

    elements = inventory["elements"]
    if not isinstance(elements, list):
        raise ValueError("inventory['elements'] must be a list")

    for idx, elem in enumerate(elements):
        if not isinstance(elem, dict):
            raise ValueError(f"element at index {idx} is not a dictionary")
        if "name" not in elem or "value" not in elem:
            raise ValueError(f"element at index {idx} must contain 'name' and 'value' keys")

    # If no checks failed, return True to indicate successful validation
    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests referenced in `manifest_files` are present in `digests_used`.

    Parameters
    ----------
    manifest_files : Mapping[str, str] | Iterable[str]
        Either a dictionary mapping filenames to digest strings or an iterable
        of digest strings.  All digests required by the manifests must be
        present in `digests_used`.
    digests_used : Mapping[str, Any] | Iterable[str] | str
        Either a mapping whose keys are the digest strings that are in use,
        an iterable of digest strings, or a single digest string.

    Raises
    ------
    ValueError
        If any digest referenced in `manifest_files` is missing from
        `digests_used`.
    """
    # Extract the set of required digests from the manifest
    if isinstance(manifest_files, dict):
        required = set()
        for value in manifest_files.values():
            if value is not None:
                required.add(str(value))
    else:
        try:
            required = {str(x) for x in manifest_files if x is not None}
        except TypeError:
            required = {str(manifest_files)} if manifest_files is not None else set()

    # Determine the set of used digests
    if isinstance(digests_used, dict):
        used = set(str(k) for k in digests_used.keys())
    else:
        try:
            used = {str(x) for x in digests_used}
        except TypeError:
            used = {str(digests_used)} if digests_used is not None else set()

    # Identify any digests that are required but not used
    missing = required - used
    if missing:
        missing_list = ', '.join(sorted(missing))
        raise ValueError(f"Missing digests referenced in manifest: {missing_list}")
    # No return value needed; function succeeds silently when all required
    # digests are present in digests_used.<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Prior must be an instance of the same validator class.
    if not isinstance(prior, self.__class__):
        raise ValueError(
            f"prior must be an instance of {self.__class__.__name__}"
        )

    # Determine a timestamp or version attribute present on both objects.
    timestamp_names = ["created_at", "timestamp", "date", "version_date", "established_date"]
    self_ts = None
    prior_ts = None
    for name in timestamp_names:
        if hasattr(self, name):
            self_ts = getattr(self, name)
            break
    for name in timestamp_names:
        if hasattr(prior, name):
            prior_ts = getattr(prior, name)
            break

    if self_ts is None or prior_ts is None:
        raise ValueError(
            "Could not find a comparable timestamp or version attribute on "
            "self or prior for validation."
        )

    try:
        if prior_ts >= self_ts:
            raise ValueError(
                "The prior inventory must have an earlier timestamp/version "
                f"than the current inventory ({prior_ts} >= {self_ts})."
            )
    except TypeError:
        raise ValueError(
            "Timestamp/type comparison failed; ensure the timestamp "
            "attributes are comparable (e.g., datetime or numeric)."
        )

    # If the inventories expose a dictionary representation, ensure the prior
    # keys are all present in the current inventory.
    if hasattr(self, "inventory") and hasattr(prior, "inventory"):
        curr_inv = getattr(self, "inventory")
        prior_inv = getattr(prior, "inventory")
        if isinstance(curr_inv, dict) and isinstance(prior_inv, dict):
            missing_keys = set(prior_inv) - set(curr_inv)
            if missing_keys:
                raise ValueError(
                    f"The current inventory is missing keys present in the "
                    f"prior inventory: {missing_keys}"
                )

    # If all checks pass, return True (or None if you prefer).
    return True<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type check: prior should be the same type as self
        if not isinstance(prior, type(self)):
            raise ValueError("prior must be an InventoryValidator of the same type")

        # Try to compare by timestamp/last_modified if available
        timestamp_attrs = ['last_modified', 'timestamp', 'updated_at', 'created_at']
        for attr in timestamp_attrs:
            if hasattr(self, attr) and hasattr(prior, attr):
                try:
                    current_ts = getattr(self, attr)
                    prior_ts = getattr(prior, attr)
                    # If the timestamps are not comparable, ignore this attribute
                    if current_ts <= prior_ts:
                        raise ValueError(f"Prior inventory ({attr}={prior_ts}) must be older than current inventory ({attr}={current_ts})")
                    # If comparison succeeded, we consider validation passed
                    return True
                except Exception:
                    # If comparison fails (e.g., different types), move to the next attribute
                    continue

        # Fallback to numeric ordering by id or version if present
        numeric_attrs = ['id', 'inventory_id', 'version']
        for attr in numeric_attrs:
            if hasattr(self, attr) and hasattr(prior, attr):
                try:
                    current_val = getattr(self, attr)
                    prior_val = getattr(prior, attr)
                    if not isinstance(current_val, (int, float)) or not isinstance(prior_val, (int, float)):
                        continue
                    if prior_val >= current_val:
                        raise ValueError(f"Prior inventory ({attr}={prior_val}) must be less than current inventory ({attr}={current_val})")
                    return True
                except Exception:
                    continue

        # If no explicit ordering attributes are found, assume validation passes
        # as no contradictions were detected.
        return True<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure correct type
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # Inventory identifier comparison (try common names)
        curr_id = getattr(self, "inventory_id", getattr(self, "id", None))
        prior_id = getattr(prior, "inventory_id", getattr(prior, "id", None))
        if curr_id is None or prior_id is None:
            raise AttributeError("Both inventories must define an identifier (id or inventory_id).")
        if curr_id != prior_id:
            raise ValueError("Inventory IDs differ between current and prior inventory.")

        # Version comparison
        curr_version = getattr(self, "version", None)
        prior_version = getattr(prior, "version", None)
        if curr_version is None or prior_version is None:
            raise AttributeError("Both inventories must define a 'version' attribute.")
        if curr_version <= prior_version:
            raise ValueError(
                "Current inventory version must be greater than the prior's version. "
                f"got {curr_version!r} <= {prior_version!r}"
            )

        # Timestamp comparison (try common names)
        curr_ts = getattr(
            self, "created_at", getattr(self, "date_created", getattr(self, "timestamp", None))
        )
        prior_ts = getattr(
            prior,
            "created_at",
            getattr(prior, "date_created", getattr(prior, "timestamp", None)),
        )
        if curr_ts is None or prior_ts is None:
            raise AttributeError(
                "Both inventories must define a timestamp-like attribute (created_at, date_created, timestamp)."
            )
        try:
            if curr_ts <= prior_ts:
                raise ValueError(
                    "Current inventory timestamp must be after the prior's timestamp. "
                    f"got {curr_ts!r} <= {prior_ts!r}"
                )
        except TypeError:
            # If timestamps are not comparable, we skip this check
            pass

        # Item set consistency: all prior items should be present in the current inventory
        curr_items = getattr(self, "items", getattr(self, "entries", getattr(self, "elements", None)))
        prior_items = getattr(prior, "items", getattr(prior, "entries", getattr(prior, "elements", None)))
        if curr_items is not None and prior_items is not None:
            missing = set(prior_items) - set(curr_items)
            if missing:
                raise ValueError(
                    f"Current inventory is missing items that were present in the prior: {missing}"
                )

        return True  # All checks passed successfully
