def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    # Try to get the data for the requested version from the inventory
    version_data = None

    # Handle inventory as a plain dict
    if isinstance(inventory, dict):
        if 'versions' in inventory:
            version_data = inventory['versions'].get(version)
        else:
            # maybe inventory itself is version keyed
            version_data = inventory.get(version)
    else:
        # Fallback: use attribute access
        try:
            versions_attr = getattr(inventory, 'versions', {})
            if isinstance(versions_attr, dict):
                version_data = versions_attr.get(version)
        except Exception:
            pass

    # If we could not locate the version, return empty mapping
    if not version_data:
        return result

    # The state mapping could be stored under several keys; search common ones
    state_map = None
    state_keys = ['state', 'paths', 'logical_paths', 'logical_path_map', 'content_map']
    for key in state_keys:
        if isinstance(version_data, dict):
            state_map = version_data.get(key)
        else:
            state_map = getattr(version_data, key, None)
        if state_map:
            break

    if not state_map:
        return result

    # Build the final logical path -> set of content files mapping
    for logical_path, files in state_map.items():
        if isinstance(files, (list, tuple, set)):
            content_set = set(files)
        else:
            # If a single file path is stored directly, wrap it in a set
            content_set = {files}
        result[logical_path] = content_set

    return result<|return|>

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    import collections

    # Helper to update a mapping with content files from a given state mapping
    def _update_mapping(mapping, state_mapping):
        for logical_path, files in state_mapping.items():
            if logical_path not in mapping:
                mapping[logical_path] = set()
            if isinstance(files, (list, tuple, set)):
                mapping[logical_path].update(files)
            else:
                # Treat a single file string as a single-element set
                mapping[logical_path].add(files)

    # Resolve a state's representation into a dict of logical_path -> files
    def _state_to_dict(state):
        """
        Accepts either a dict mapping logical_path to files, or a
        list/tuple of dicts each containing 'logical_path' and
        'content_files' keys. Returns a dict mapping logical_path to
        an iterable of files.
        """
        if isinstance(state, dict):
            # Determine if keys look like logical paths or if there is a
            # 'logical_path' key; if none of the values are dicts, assume
            # it's already the mapping we want
            if all(not isinstance(v, dict) for v in state.values()):
                return state
            # Otherwise, look for 'logical_path' in each value
            result = {}
            for v in state.values():
                if isinstance(v, dict) and 'logical_path' in v:
                    lp = v['logical_path']
                    files = v.get('content_files', [])
                    result[lp] = files
            return result
        elif isinstance(state, (list, tuple)):
            result = {}
            for item in state:
                if isinstance(item, dict):
                    lp = item.get('logical_path')
                    files = item.get('content_files', [])
                    if lp is not None:
                        result[lp] = files
            return result
        else:
            return {}

    # Build the base mapping for the requested version
    base_states = inventory.get(version, {})
    base_mapping = _state_to_dict(base_states)

    # Create a mapping that will hold the final result
    result = collections.defaultdict(set)

    # Add the base state's content files
    _update_mapping(result, base_mapping)

    # Now include content files from later versions
    # Sort the available versions; assume they can be compared directly
    later_versions = []
    try:
        later_versions = sorted([v for v in inventory.keys() if v > version])
    except TypeError:
        # If versions are of different comparable types, skip ordering
        later_versions = [v for v in inventory.keys() if v != version]

    for later_version in later_versions:
        later_states = inventory.get(later_version, {})
        later_mapping = _state_to_dict(later_states)
        _update_mapping(result, later_mapping)

    # Convert defaultdict to a normal dict
    return dict(result)<|return|>

