def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to collect content files from a single source entry
    def _add_to_map(lp_map, logical_path, content_file):
        if logical_path is None:
            return
        if logical_path not in lp_map:
            lp_map[logical_path] = set()
        if isinstance(content_file, (list, tuple)):
            for cf in content_file:
                if cf:
                    lp_map[logical_path].add(cf)
        elif content_file:
            lp_map[logical_path].add(content_file)

    logical_path_map = {}

    # Case 1: inventory is a dict mapping {version: {logical_path: content_file}}
    if isinstance(inventory, dict):
        # Direct mapping for the target version
        if version in inventory:
            for lp, cf in inventory[version].items():
                _add_to_map(logical_path_map, lp, cf)
        # Include duplicates from later versions
        for ver in inventory:
            if ver > version:
                for lp, cf in inventory[ver].items():
                    _add_to_map(logical_path_map, lp, cf)
    else:
        # Case 2: inventory is a list of entries (e.g., dicts with keys 'version',
        # 'logical_path', 'content_file')
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            ent_ver = entry.get("version")
            if ent_ver == version:
                lp = entry.get("logical_path")
                cf = entry.get("content_file")
                _add_to_map(logical_path_map, lp, cf)
            elif ent_ver is not None and ent_ver > version:
                # Duplicate entry from later version
                lp = entry.get("logical_path")
                cf = entry.get("content_file")
                _add_to_map(logical_path_map, lp, cf)

    return logical_path_map
