def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")
        required_keys = {"algorithm", "files"}
        allowed_keys = required_keys.union({"checksum_method"})
        missing_keys = required_keys - set(fixity.keys())
        if missing_keys:
            raise ValueError(f"Missing required keys in fixity: {missing_keys}")

        algorithm = fixity.get("algorithm")
        if not isinstance(algorithm, str):
            raise ValueError("Fixity 'algorithm' must be a string")
        # Recognise a few common algorithms – extend as needed
        known_algorithms = {"md5", "sha1", "sha256", "sha512"}
        if algorithm.lower() not in known_algorithms:
            raise ValueError(f"Unsupported algorithm '{algorithm}'. Known: {known_algorithms}")

        files = fixity.get("files")
        if not isinstance(files, list):
            raise ValueError("Fixity 'files' must be a list")
        if not files:
            raise ValueError("Fixity 'files' list must contain at least one entry")

        # Prepare a set for quick lookup
        manifest_set = set(manifest_files)

        referenced_set = set()
        for entry in files:
            if not isinstance(entry, dict):
                raise ValueError("Each item in fixity 'files' must be a dictionary")
            if "filename" not in entry or "checksum" not in entry:
                raise ValueError("Each file entry must contain 'filename' and 'checksum'")
            filename = entry["filename"]
            checksum = entry["checksum"]
            if filename in referenced_set:
                raise ValueError(f"Duplicate reference to file '{filename}' in fixity")
            referenced_set.add(filename)
            if filename not in manifest_set:
                raise ValueError(f"File '{filename}' referenced in fixity but not present in manifest")
            if not all(c in "0123456789abcdefABCDEF" for c in checksum):
                raise ValueError(f"Checksum for '{filename}' contains non-hex characters")
            # Optional length check based on algorithm hash size
            expected_length = {
                "md5": 32,
                "sha1": 40,
                "sha256": 64,
                "sha512": 128,
            }.get(algorithm.lower())
            if expected_length and len(checksum) != expected_length:
                raise ValueError(
                    f"Checksum length for '{filename}' does not match expected length {expected_length} for algorithm {algorithm}"
                )

        # Additional sanity: ensure no extra keys
        extraneous_keys = set(fixity.keys()) - allowed_keys
        if extraneous_keys:
            raise ValueError(f"Unrecognized keys in fixity: {extraneous_keys}")

        return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

