def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError('Fixity block must be a dictionary')

        # The block is expected to contain a key pointing to a list of file entries
        files_key = 'files'
        if files_key not in fixity:
            raise ValueError('Missing "files" key in fixity block')

        files_entries = fixity[files_key]
        if not isinstance(files_entries, list):
            raise ValueError('"files" key must map to a list')

        for entry in files_entries:
            if not isinstance(entry, dict):
                raise ValueError('Each entry in fixity "files" list must be a dict')

            if 'path' not in entry:
                raise ValueError('Each entry in fixity "files" list must have a "path" key')
            path = entry['path']
            if path not in manifest_files:
                raise ValueError(f'File "{path}" in fixity block is not listed in the manifest')

            if 'hash' not in entry:
                raise ValueError('Each entry in fixity "files" list must have a "hash" key')
            if not isinstance(entry['hash'], str):
                raise ValueError('The "hash" value must be a string')

        # If all checks pass, validation succeeded
        return True<|return|>

