def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Mapping from basename to dict of extensions to file content
    collected = {}

    for root, _, files in os.walk(folder):
        for fn in files:
            name, ext = os.path.splitext(fn)
            ext = ext[1:].lower()  # remove leading dot, normalize case
            if not ext:
                continue  # skip files without extension
            path = os.path.join(root, fn)
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except (OSError, UnicodeDecodeError):
                # If the file can't be read, store None
                content = None
            if name not in collected:
                collected[name] = {}
            collected[name][ext] = content

    # Keep only entries that have an 'xml' file and its content is not None
    result = {
        name: data
        for name, data in collected.items()
        if 'xml' in data and data['xml'] is not None
    }

    return result<|return|>

def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        # Initialize storage containers if they don't exist
        if not hasattr(self, "_renditions"):
            self._renditions = {}
        if not hasattr(self, "_originals"):
            self._originals = {}

        # Determine the original file name by stripping the language suffix
        ext_start = file_path.rfind('.')
        if ext_start == -1:
            original = file_path
        else:
            base = file_path[:ext_start]
            dash = base.rfind('-')
            if dash == -1:
                original = file_path
            else:
                original = base[:dash] + file_path[ext_start:]

        # Ensure there is a dict for the original entry
        if original not in self._renditions:
            self._renditions[original] = {}
            self._originals[original] = original

        # Store the rendition for the given language
        self._renditions[original][lang] = file_path

        # Return the updated dict for convenience
        return self._renditions[original]<|return|>

