def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath_expr in pubdate_xpaths:
        try:
            matches = node.xpath(xpath_expr)
        except Exception:
            continue
        if not matches:
            continue
        # If the match is already a string, return it directly
        first_match = matches[0]
        if isinstance(first_match, str):
            return first_match.strip()
        # Otherwise, try to extract the string value of the element
        try:
            # lxml supports 'string(.)' to get text content
            text_value = node.xpath(
                f"{xpath_expr}/string(.)"
            )
            if text_value:
                return text_value[0].strip()
        except Exception:
            pass
        # Fallback: use text_content() if available
        if hasattr(first_match, "text_content"):
            return first_match.text_content().strip()
        # Fallback: use .text or .tail
        if hasattr(first_match, "text") and first_match.text:
            return first_match.text.strip()
        if hasattr(first_match, "tail") and first_match.tail:
            return first_match.tail.strip()
    return None<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Recursive formatter that handles common containers and objects
    def _format(obj, level):
        spacer = ' ' * level
        if isinstance(obj, dict):
            lines = []
            for key, value in obj.items():
                lines.append(f"{spacer}{key}:")
                lines.append(_format(value, level + 2))
            return '\n'.join(lines)
        elif isinstance(obj, (list, tuple, set)):
            lines = []
            for item in obj:
                lines.append(_format(item, level + 2))
            return '\n'.join(lines)
        elif hasattr(obj, "__dict__") and not callable(obj):
            lines = []
            for attr, value in obj.__dict__.items():
                lines.append(f"{spacer}{attr}:")
                lines.append(_format(value, level + 2))
            return '\n'.join(lines)
        else:
            if debug:
                return f"{spacer}{repr(obj)} ({type(obj).__name__})"
            return f"{spacer}{repr(obj)}"

    return _format(self, indent)<|return|>

