                lines.append(f'{spacer}    ]')
            elif isinstance(val, dict):
                lines.append(f'{spacer}    {key}: {{')
                for k, v in val.items():
                    if hasattr(v, 'pretty'):
                        v_str = v.pretty(indent + 8, debug).strip()
                        lines.append(f'{spacer}        {repr(k)}: {v_str}')
