                        lines.append(f'{spacer}        {repr(k)}: {repr(v)}')
                lines.append(f'{spacer}    }}')
            else:
                if debug:
                    lines.append(f'{spacer}    {key} ({type(val).__name__}): {repr(val)}')
                else:
                    lines.append(f'{spacer}    {key}: {repr(val)}')
