            items = []
            for k, v in sorted(obj.items()):
                key_str = repr(k)
                val_str = _format(v, level + 2)
                if debug:
                    val_str = f'{type(v).__name__} {val_str}'
                items.append(f'{prefix}  {key_str}: {val_str}')
