            if isinstance(obj, list):
                open_sym, close_sym = '[', ']'
            elif isinstance(obj, tuple):
                open_sym, close_sym = '(', ')'
            else:
                open_sym, close_sym = '{', '}'
            items = []
            for item in obj:
                item_str = _format(item, level + 2)
                if debug:
                    item_str = f'{type(item).__name__} {item_str}'
                items.append(f'{prefix}  {item_str}')
            inner = '\n'.join(items)
            return f'{open_sym}\n{inner}\n{prefix}{close_sym}'
        if hasattr(obj, '__dict__'):
            cls_name = obj.__class__.__name__
            attrs = []
            for attr in sorted(obj.__dict__):
                val = obj.__dict__[attr]
                val_str = _format(val, level + 2)
                if debug:
                    val_str = f'{type(val).__name__} {val_str}'
                attrs.append(f'{prefix}  {attr} = {val_str}')
            inner = '\n'.join(attrs)
            return f'{cls_name}(\n{inner}\n{prefix})'
        return repr(obj)
    return _format(self, indent)<|return|>

