def get_versions():
    """
    Get version information or return default if unable to do so.

    Returns:
        dict: A dictionary containing at least two keys:
              - 'version': a string representing the package version;
              - 'commit': a short git revision hash if available, otherwise 'unknown'.
    """
    version = "0.0.0"
    commit = "unknown"

    # Attempt to import the metadata module (Python 3.8+ or backport)
    try:
        import importlib.metadata as metadata
    except Exception:
        try:
            import importlib_metadata as metadata  # type: ignore
        except Exception:
            return {"version": version, "commit": commit}

    # Infer the package name
    package_name = __package__
    if not package_name:
        try:
            import os, sys
            package_name = os.path.splitext(os.path.basename(sys.argv[0]))[0]
        except Exception:
            package_name = None

    # Retrieve the version from package metadata
    if package_name:
        try:
            version = metadata.version(package_name)
        except Exception:
            pass

    # Attempt to get the current git commit hash
    try:
        import subprocess
        commit = (
            subprocess.check_output(
                ["git", "rev-parse", "--short", "HEAD"],
                stderr=subprocess.DEVNULL,
            )
            .decode("utf-8")
            .strip()
        )
    except Exception:
        pass

    return {"version": version, "commit": commit}<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to get distribution version via importlib.metadata
    try:
        from importlib.metadata import version, PackageNotFoundError
    except ImportError:
        # For older Python (<3.8) with backport
        try:
            from importlib_metadata import version, PackageNotFoundError  # type: ignore
        except ImportError:
            version = None  # type: ignore

    if version is not None:
        # Make a best effort to infer the distribution name from module path
        try:
            import os
            module_dir = os.path.dirname(__file__)  # directory containing this file
            dist_name = os.path.basename(module_dir) or None
            if dist_name:
                try:
                    return version(dist_name)
                except (PackageNotFoundError, ValueError):
                    pass
        except Exception:
            pass

    # Fallback: look for a VERSION or version.txt file alongside this module
    try:
        import os
        module_dir = os.path.dirname(__file__)
        for fname in ("VERSION", "version.txt"):
            file_path = os.path.join(module_dir, fname)
            if os.path.isfile(file_path):
                with open(file_path, "r", encoding="utf-8") as f:
                    return f.read().strip()
    except Exception:
        pass

    # Ultimate fallback: return a default marker
    return "0+unknown"<|return|>

