    # Normalise pieces and convert to strings
    parts = [str(p) if p is not None else None for p in pieces]
    # Early exit: empty input
    if not parts or all(p is None for p in parts):
        return ""

    # Helper to generate base version string from major/minor/patch
    def base_version():
        # Only take the first three parts that are not None
        base_parts = [p for p in parts[:3] if p is not None]
        # If all three are none, fallback to any non-none part
