        # Expect prerelease type at index 3, number at index 4
        pre_type = parts[3] if len(parts) > 3 else None
        pre_num = parts[4] if len(parts) > 4 else None
        if pre_type:
            pre_str = pre_type
            if pre_num:
                pre_str += str(pre_num)
            return f"{base}-{pre_str}"
        else:
            return base

    if style.lower() == "pep440":
        base = base_version()
        # PEP 440 prereleases: a (alpha), b (beta), rc, dev
        mapping = {"alpha": "a", "beta": "b", "rc": "rc", "dev": "dev"}
        pre_type = parts[3] if len(parts) > 3 else None
        pre_num = parts[4] if len(parts) > 4 else None
        if pre_type:
            mapped = mapping.get(pre_type.lower(), pre_type.lower())
            pre_str = mapped
            if pre_num:
                pre_str += str(pre_num)
            return f"{base}{pre_str}"
        else:
            return base

    # Default plain style: dot-separated, ignoring None
    plain_parts = [p for p in parts if p is not None]
    return ".".join(plain_parts)
