def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects) - number of objects checked and number of objects that passed validation
    """
    # Determine the iterable of objects to validate
    if hasattr(self, "objects") and hasattr(self, "__iter__"):
        objects = self.objects
    elif hasattr(self, "items") and hasattr(self.items, "__iter__"):
        objects = self.items
    elif hasattr(self, "children") and callable(self.children):
        objects = self.children()
    elif hasattr(self, "children") and hasattr(self.children, "__iter__"):
        objects = self.children
    else:
        objects = []

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Object-specific validation method
        if validate_objects:
            validate_func = getattr(obj, "validate", None)
            if callable(validate_func):
                try:
                    if not validate_func():
                        is_valid = False
                except Exception:
                    is_valid = False

        # Optional digest check
        if check_digests and is_valid:
            digest_func = getattr(obj, "compute_digest", None)
            expected_digest = getattr(obj, "digest", None)
            if callable(digest_func) and expected_digest is not None:
                try:
                    if digest_func() != expected_digest:
                        is_valid = False
                except Exception:
                    is_valid = False

        if is_valid:
            good_objects += 1
        elif show_warnings:
            try:
                obj_repr = repr(obj)
            except Exception:
                obj_repr = "<unrepresentable object>"
            print(f"Validation failed for object: {obj_repr}")

    return num_objects, good_objects<|return|>

