def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Helper to iterate over all objects recursively. This function
    # simply looks for an attribute named "children" (or "sub_objects")
    # and walks each child. It also yields the container object
    # itself so callers can validate the container if needed.
    def _iter_objects(start):
        stack = [start]
        while stack:
            obj = stack.pop()
            # yield the object itself for validation
            yield obj
            # identify children; support common container patterns
            if hasattr(obj, "children") and obj.children:
                stack.extend(obj.children)
            elif hasattr(obj, "sub_objects") and obj.sub_objects:
                stack.extend(obj.sub_objects)
            elif isinstance(getattr(obj, "items", None), list):
                stack.extend(getattr(obj, "items", []))
            elif isinstance(getattr(obj, "keys", None), list):
                stack.extend(getattr(obj, "keys", []))
            # if the object itself is a list or dict, walk its elements
            if isinstance(obj, dict):
                stack.extend(obj.values())
                stack.extend(obj.keys())
            elif isinstance(obj, (list, tuple, set)):
                stack.extend(obj)

    num_objects = 0
    good_objects = 0

    for obj in _iter_objects(self):
        num_objects += 1
        try:
            is_valid = True

            # Validate object integrity if requested.
            if validate_objects:
                # First try a custom validator method if present.
                if hasattr(obj, "is_valid"):
                    is_valid &= bool(obj.is_valid())
                # Fall back to a generic check: attribute `valid` must be True.
                elif hasattr(obj, "valid"):
                    is_valid &= bool(obj.valid)
                # If no validator exists, assume it's fine.
                else:
                    is_valid &= True

            # Validate digests if requested.
            if check_digests:
                # Try a digest method if provided.
                if hasattr(obj, "digest"):
                    # Some objects might expose an "expected_digest" or "checksum".
                    expected = getattr(obj, "expected_digest", None)
                    if expected is None:
                        expected = getattr(obj, "checksum", None)
                    if expected is not None:
                        is_valid &= (obj.digest() == expected)
                # Some objects might store a precomputed hash directly.
                elif hasattr(obj, "hash"):
                    expected = getattr(obj, "hash", None)
                    if expected is not None and hasattr(obj, "compute_hash"):
                        is_valid &= (obj.compute_hash() == expected)

            if is_valid:
                good_objects += 1

