def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Determine iterable collection of objects in the hierarchy
        if hasattr(self, "objects") and isinstance(self.objects, (list, tuple)):
            objects_iter = self.objects
        elif hasattr(self, "storage"):
            storage = self.storage
            if isinstance(storage, dict):
                objects_iter = storage.values()
            elif isinstance(storage, (list, tuple)):
                objects_iter = storage
            else:
                objects_iter = []
        else:
            objects_iter = []

        for obj in objects_iter:
            num_objects += 1
            is_valid = True

            # Validate object if requested
            if validate_objects:
                try:
                    if hasattr(obj, "validate"):
                        # Assume validate() returns bool
                        if not obj.validate():
                            is_valid = False
                    else:
                        # If no validate method, consider it valid
                        pass
                except Exception:
                    is_valid = False

            # Check digests if requested
            if check_digests and is_valid:
                try:
                    # Common digest attribute names
                    cmp_attrs = []
                    if hasattr(obj, "checksum"):
                        cmp_attrs.append(("checksum", getattr(obj, "checksum")))
                    if hasattr(obj, "digest"):
                        cmp_attrs.append(("digest", getattr(obj, "digest")))
                    if hasattr(obj, "compute_digest"):
                        comp_val = obj.compute_digest()
                    else:
                        comp_val = None

                    for name, stored_val in cmp_attrs:
                        if comp_val is None:
                            is_valid = False
                            break
                        if stored_val != comp_val:
                            is_valid = False
                            break
                except Exception:
                    is_valid = False

            if is_valid:
                good_objects += 1
            elif show_warnings:
                try:
                    obj_repr = str(obj)
                except Exception:
                    obj_repr = "<unrepresentable object>"
                print(f"Warning: object {obj_repr} failed validation.")

        return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def walk(node):
        nonlocal num_objects, good_objects
        if node is None:
            return
        if isinstance(node, dict):
            for val in node.values():
                walk(val)
        elif isinstance(node, (list, tuple, set)):
            for item in node:
                walk(item)
        else:
            # Treat the node as an object to validate
            num_objects += 1
            is_valid = True

            if validate_objects:
                if hasattr(node, 'validate') and callable(node.validate):
                    try:
                        if not node.validate():
                            is_valid = False
                    except Exception as exc:
                        if show_warnings:
                            print(f"Warning: validation error for {node}: {exc}")
                        is_valid = False
                else:
                    if show_warnings:
                        print(f"Warning: object {node} has no validate() method")

            if check_digests:
                if hasattr(node, 'digest'):
                    if hasattr(node, 'compute_digest') and callable(node.compute_digest):
                        try:
                            if node.digest != node.compute_digest():
                                if show_warnings:
                                    print(f"Warning: digest mismatch for {node}")
                                is_valid = False
                        except Exception as exc:
                            if show_warnings:
                                print(f"Warning: error computing digest for {node}: {exc}")
                            is_valid = False
                    else:
                        if show_warnings:
                            print(f"Warning: object {node} has no compute_digest() method")
                else:
                    if show_warnings:
                        print(f"Warning: object {node} has no digest attribute")

            if is_valid:
                good_objects += 1

    # Determine the root of the hierarchy
    root = getattr(self, 'root', None)
    if root is None:
        root = getattr(self, 'hierarchy', None)
    if root is None:
        raise AttributeError("No 'root' or 'hierarchy' attribute found on self")

    walk(root)
    return num_objects, good_objects<|return|>

def validate_version_inventories(self, version_dirs):
    """
    Verify that each version has a complete inventory and that all digests are
    consistent with the previous version. Record any digest differences
    between the latest inventory and the root inventory for later checks.
    """
    # Ensure we have a place to store digest differences
    if not hasattr(self, "digest_differences"):
        self.digest_differences = {}

    # Load the root inventory once, if we haven't already
    if not hasattr(self, "_root_inventory_cache"):
        root_inv_path = os.path.join(self.base_path, "inventory.json")
        if not os.path.isfile(root_inv_path):
            raise AssertionError(f"Root inventory missing at {root_inv_path}")
        with open(root_inv_path, "r", encoding="utf-8") as f:
            self._root_inventory_cache = json.load(f)

    previous_inventory = None

    for idx, version in enumerate(version_dirs, start=1):
        inv_path = os.path.join(self.base_path, version, "inventory.json")
        if not os.path.isfile(inv_path):
            raise AssertionError(f"Inventory missing for version {version}")

        with open(inv_path, "r", encoding="utf-8") as f:
            current_inventory = json.load(f)

        if previous_inventory is not None:
            # Check that no new files are introduced
            added = set(current_inventory) - set(previous_inventory)
            if added:
                raise AssertionError(
                    f"Version {version} introduces new files: {sorted(added)}"
                )
            # Check that no files are removed
            removed = set(previous_inventory) - set(current_inventory)
            if removed:
                raise AssertionError(
                    f"Version {version} removes files: {sorted(removed)}"
                )
            # Check that digests match
            for path, prev_digest in previous_inventory.items():
                curr_digest = current_inventory[path]
                if prev_digest != curr_digest:
                    # Record a mismatch so it can be inspected later
                    self.digest_differences.setdefault(path, []).append(
                        {"version": version, "prev_digest": prev_digest, "curr_digest": curr_digest}
                    )

        # After checking against the previous, compare against the root
        root_inv = self._root_inventory_cache
        for path, root_digest in root_inv.items():
            if path not in current_inventory:
                raise AssertionError(
                    f"File {path} from root inventory missing in version {version}"
                )
            curr_digest = current_inventory[path]
            if root_digest != curr_digest:
                self.digest_differences.setdefault(path, []).append(
                    {"type": "root_mismatch", "prev_digest": root_digest, "curr_digest": curr_digest}
                )

        previous_inventory = current_inventory

    # The function doesn't return a value; any mismatches raise AssertionError
    return None
<|return|>

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os

        if not version_dirs:
            return

        # Helper to load an inventory file into a dict {name: digest}
        def load_inventory(path):
            if not os.path.isfile(path):
                raise FileNotFoundError(f"Missing inventory at {path}")
            inventory = {}
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue  # skip malformed lines
                    name, digest = parts
                    inventory[name] = digest
            return inventory

        # Load the root inventory (the first version in sequence)
        root_inventory_path = os.path.join(version_dirs[0], "inventory.txt")
        root_inventory = load_inventory(root_inventory_path)

        # Record of digests that differ from root
        differing = {}

        # Validate each version directory
        for idx, vd in enumerate(version_dirs, start=1):
            inv_path = os.path.join(vd, "inventory.txt")
            inv = load_inventory(inv_path)

            # Ensure the inventory contains all names present in the root inventory
            missing = set(root_inventory) - set(inv)
            if missing:
                raise ValueError(f"Version {idx} ({vd}) inventory missing items: {sorted(missing)}")

            # Record digest differences (only for names that exist in both inventories)
            for name, root_digest in root_inventory.items():
                cur_digest = inv.get(name)
                if cur_digest is None:
                    continue
                if cur_digest != root_digest:
                    differing.setdefault(name, []).append((vd, cur_digest))

        # Store the record on the instance for later checks
        self._different_digests = differing

        return</details><|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root
    inventory so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be
    in version sequence (1, 2, 3...).
    """
    import os
    import json

    # Ensure required attributes exist
    if not hasattr(self, "root_inventory"):
        raise AttributeError("root_inventory attribute is required")
    if not hasattr(self, "inventory_differences"):
        self.inventory_differences = {}
    if not hasattr(self, "validation_errors"):
        self.validation_errors = []

    root_inv = self.root_inventory or {}
    differences = {}
    errors = []

    for vdir in version_dirs:
        # Build path to the expected inventory file
        inv_path = os.path.join(vdir, "inventory.json")

        if not os.path.isfile(inv_path):
            errors.append(f"Missing inventory in {vdir}")
            continue

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            errors.append(f"Failed to load inventory from {vdir}: {exc}")
            continue

        # inv is expected to be a mapping of item -> digest
        for item, digest in inv.items():
            root_digest = root_inv.get(item)
            if root_digest is None:
                # New item introduced in this version; treat as difference
                differences.setdefault(vdir, {})[item] = (digest, None)
            elif digest != root_digest:
                differences.setdefault(vdir, {})[item] = (digest, root_digest)

        # Also check for items that existed in root but are missing in this version
        for item in root_inv:
            if item not in inv:
                differences.setdefault(vdir, {})[item] = ("<missing>", root_inv[item])

    # Store results on the instance
    self.inventory_differences = differences
    self.validation_errors = errors

    # Return True if no errors were found
    return not errors
<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Check existence
    if not os.path.exists(path):
        return f"path '{path}' does not exist"

    # File case
    if os.path.isfile(path):
        return "file"

    if not os.path.isdir(path):
        return f"unknown type for '{path}'"

    # Directory case: first look for '0=' files in this directory
    try:
        for entry in os.scandir(path):
            if entry.is_file() and entry.name.startswith("0="):
                return "object"
    except OSError as e:
        return f"cannot read directory '{path}': {e}"

    # If not found, look into immediate subdirectories for '0=' files
    try:
        for subentry in os.scandir(path):
            if subentry.is_dir():
                subdir = subentry.path
                for subfile in os.scandir(subdir):
                    if subfile.is_file() and subfile.name.startswith("0="):
                        return "root"
    except OSError as e:
        return f"cannot read subdirectories of '{path}': {e}"

    return f"unrecognized directory structure at '{path}'"<|return|>

def find_path_type(path):
    os = __import__('os')
    fnmatch = __import__('fnmatch')
    if not os.path.lexists(path):
        return f"not found: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        # Check for OCFL storage root indicator
        if os.path.lexists(os.path.join(path, 'OCFL_VERSION')):
            return 'root'
        # Look for a Namaste file named '0=*'
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"access error: {e}"
        for name in entries:
            if fnmatch.fnmatch(name, '0=*'):
                return 'object'
        return f"directory but no Namaste file: {path}"
    return f"unknown type for {path}"<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Make sure params is a dict and prepare a shallow copy to avoid side‑effects
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Normalise bug_ids to a comma separated string suitable for Bugzilla
    if bug_ids:
        # If a string is provided, use it as is
        if isinstance(bug_ids, (str, bytes)):
            ids_str = bug_ids
        else:
            try:
                ids = list(bug_ids)
            except Exception:
                ids = [bug_ids]
            ids_str = ",".join(map(str, ids))
        params["ids"] = ids_str

    # Ensure that at least a minimal set of fields is requested
    if "include_fields" not in params:
        params["include_fields"] = "all"

    return params<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a mutable dictionary
    if params is None:
        params = {}
    # If no bug IDs provided, return params unchanged
    if not bug_ids:
        return params
    # Convert all bug identifiers to non‑empty strings
    bug_ids_str = [str(bug_id).strip() for bug_id in bug_ids if str(bug_id).strip()]
    if not bug_ids_str:
        return params
    # Append the new IDs to an existing 'bug_id' key if present
    existing = params.get("bug_id")
    if existing:
        # Preserve original ordering and allow duplicates
        existing_parts = [part.strip() for part in str(existing).split(",") if part.strip()]
        params["bug_id"] = ",".join(existing_parts + bug_ids_str)
    else:
        params["bug_id"] = ",".join(bug_ids_str)
    # Return the modified params dictionary
    return params<|return|>

