def deep_merge_nodes(nodes):
    '''Deep merge a list of (ScalarNode, value) tuples, where value may be a MappingNode or other Node.'''
    # Helper to merge two values associated with the same key
    def merge_nodes_vals(a_val, b_val):
        # Determine if a_val is a MappingNode by its tag
        a_tag = getattr(a_val, 'tag', None)
        b_tag = getattr(b_val, 'tag', None)
        is_a_map = a_tag == 'tag:yaml.org,2002:map'
        is_b_map = b_tag == 'tag:yaml.org,2002:map'

        if is_a_map and is_b_map:
            # Merge mapping values recursively
            # Get the list of (scalar, value) pairs
            a_items = getattr(a_val, 'value', [])
            b_items = getattr(b_val, 'value', [])
            # Merge into dict keyed by scalar value
            merged_items = {}
            for k, v in a_items + b_items:
                key_str = getattr(k, 'value', None)
                if key_str in merged_items:
                    merged_items[key_str] = merge_nodes_vals(merged_items[key_str][1], v)
                else:
                    merged_items[key_str] = (k, v)
            # Build new list preserving order: first from a_items, then from b_items that are new
            new_list = []
            seen_keys = set()
            for k, v in a_items:
                key_str = getattr(k, 'value', None)
                seen_keys.add(key_str)
                new_list.append((k, merged_items[key_str][1]))
            for k, v in b_items:
                key_str = getattr(k, 'value', None)
                if key_str not in seen_keys:
                    new_list.append((k, merged_items[key_str][1]))
            # Construct new MappingNode preserving the original tag
            new_map = type(a_val)(a_tag, new_list)
            return new_map
        else:
            # Non-mapping values: last wins
            return b_val

    # Main merging loop
    merged = {}
    for key_node, val_node in nodes:
        key_str = getattr(key_node, 'value', None)
        if key_str in merged:
            # Merge the values
            merged_val = merge_nodes_vals(merged[key_str][1], val_node)
            merged[key_str] = (merged[key_str][0], merged_val)
        else:
            merged[key_str] = (key_node, val_node)

    # Return list of tuples
    return list(merged.values())
<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper functions for merging
    def merge_nodes(existing, new):
        """Merge two ruamel.yaml nodes. If both are MappingNode, deep merge them; otherwise, return new."""
        if isinstance(existing, MappingNode) and isinstance(new, MappingNode):
            return merge_mappingnode(existing, new)
        return new

    def merge_mappingnode(m1, m2):
        """Deep-merge two MappingNode objects."""
        # Build a lookup of key value to (key_node, value_node)
        dict1 = {k.value: (k, v) for k, v in m1.value}
        dict2 = {k.value: (k, v) for k, v in m2.value}

        merged_items = []

        # Process keys from first mapping
        for key, (k_node1, v_node1) in dict1.items():
            if key in dict2:
                # Merge the values for this key
                merged_items.append((k_node1, merge_nodes(v_node1, dict2[key][1])))
            else:
                merged_items.append((k_node1, v_node1))

        # Add keys that only exist in the second mapping
        for key, (k_node2, v_node2) in dict2.items():
            if key not in dict1:
                merged_items.append((k_node2, v_node2))

        return MappingNode(tag=m1.tag, value=merged_items)

    # Main merging logic
    merged = {}            # maps key value to (key_node, merged_value)
    order = []             # maintain order of first appearance

    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            # If the key node doesn't have a 'value' attribute, skip it
            continue
        key = key_node.value
        if key not in merged:
            # First time seeing this key
            merged[key] = (key_node, value_node)
            order.append(key)
        else:
            # Merge with existing value
            _, existing_value = merged[key]
            merged[key] = (key_node, merge_nodes(existing_value, value_node))

    # Build result list preserving original order of first appearance
    result = [(merged[key][0], merged[key][1]) for key in order]
    return result<|return|>

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, valueNode) tuples, deep merging values for duplicate keys.
    Non-mapping values are overridden by the last one seen.
    """
    def _merge_mapping_nodes(a, b):
        """Recursively merge two MappingNode objects."""
        a_dict = {}
        for k_node, v_node in a.value:
            a_dict[k_node.value] = (k_node, v_node)
        for k_node, v_node in b.value:
            key = k_node.value
            if key in a_dict:
                _, existing_v = a_dict[key]
                if getattr(existing_v, "tag", None) == "tag:yaml.org,2002:map" and getattr(v_node, "tag", None) == "tag:yaml.org,2002:map":
                    merged_v = _merge_mapping_nodes(existing_v, v_node)
                else:
                    merged_v = v_node
                a_dict[key] = (k_node, merged_v)
            else:
                a_dict[key] = (k_node, v_node)
        merged_list = [(k_n, v_n) for _, (k_n, v_n) in a_dict.items()]
        return MappingNode(tag="tag:yaml.org,2002:map", value=merged_list)

    merged_map = {}
    for key_node, value_node in nodes:
        key = key_node.value
        existing = merged_map.get(key)
        if existing is not None:
            if getattr(existing, "tag", None) == "tag:yaml.org,2002:map" and getattr(value_node, "tag", None) == "tag:yaml.org,2002:map":
                merged_map[key] = _merge_mapping_nodes(existing, value_node)
            else:
                merged_map[key] = value_node
        else:
            merged_map[key] = value_node

    # Preserve the key node from the last occurrence of each key
    last_key_nodes = {}
    for key_node, _ in reversed(nodes):
        if key_node.value not in last_key_nodes:
            last_key_nodes[key_node.value] = key_node

    # Build the result list in the order of first appearance of each key
    result = []
    seen = set()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in seen:
            result.append((last_key_nodes[key], merged_map[key]))
            seen.add(key)
    return result
<|return|>

