def parse_arguments(*unparsed_arguments):
    import argparse
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')
    ns = parser.parse_args(unparsed_arguments)
    name = getattr(ns, 'subparser_name', None)
    if name:
        return {name: ns}
    return {'global': ns}<|return|>

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).'''
    namespaces = {}
    unknown_by_parser = {}
    for name, parser in subparsers.items():
        # parse_known_args will parse what it can and return unknown arguments
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        namespaces[name] = namespace
        unknown_by_parser[name] = unknown

    # Find arguments that were unknown to every subparser
    if unknown_by_parser:
        common_unknown = set.intersection(*(set(u) for u in unknown_by_parser.values()))
    else:
        common_unknown = set()

    remaining = [arg for arg in unparsed_arguments if arg in common_unknown]
    return namespaces, remaining<|return|>

