def _replace_url_args(url, url_args):
    """
    Replace any custom string URL items with values in args.
    The URL is expected to contain placeholder items in the form `{name}`.
    If `url_args` is a dictionary, the placeholders are replaced using
    keyword substitution (`url.format(**url_args)`).  If `url_args` is not a
    dictionary, positional substitution is attempted (`url.format(*url_args)`).
    If the standard `format` call fails, a simple fallback replacement is
    performed.
    """
    if not url:
        return url
    # When url_args is a mapping, use keyword formatting
    if isinstance(url_args, dict):
        try:
            return url.format(**url_args)
        except Exception:
            # fallback: replace manually
            for key, value in url_args.items():
                url = url.replace('{' + str(key) + '}', str(value))
            return url
    # When url_args is an iterable, use positional formatting
    try:
        return url.format(*url_args)
    except Exception:
        # fallback: replace "{}" placeholders sequentially
        parts = url.split('{}')
        if len(parts) - 1 != len(list(url_args)):
            # unmatched placeholder count; return as-is
            return url
        result = []
        for i, part in enumerate(parts[:-1]):
            result.append(part)
            result.append(str(list(url_args)[i]))
        result.append(parts[-1])
        return ''.join(result)<|return|>

