    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Try to extract name and default from a regex match object
    try:
        if hasattr(matcher, "group"):
            name = matcher.group(1)
            # Default may or may not exist
            if matcher.lastindex is not None and matcher.lastindex >= 2:
                default = matcher.group(2)
            else:
                default = None
        else:
            # Fallback: treat matcher as a sequence or mapping
            # Sequence: first element is name, second (optional) is default
            name = matcher[0]
            default = matcher[1] if len(matcher) > 1 else None
    except Exception:
        raise ValueError("matcher format not supported")

    value = os.getenv(name)
    if value is not None:
        return value
    if default is not None:
        return default

    raise Exception(f"Environment variable '{name}' not set and no default value provided.")<|return|>

