    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from the matcher argument.
    # The matcher can be a tuple/list like ('VAR', 'default') or a string like 'VAR:default'.
    if isinstance(matcher, (list, tuple)):
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, str):
        # Support a simple "NAME:DEFAULT" syntax for string matchers
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher)}")

    # Retrieve the environment variable
    value = os.environ.get(name)
    # If not found, use default if provided or raise an error
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not set and no default provided")
    return value<|return|>

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")
    parsed = urllib.parse.urlparse(image_href)
    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme '{parsed.scheme}'. Only http and https are supported.")
    if not parsed.netloc:
        raise ValueError("URL must contain a network location (netloc).")
    # Extract image_id from the path; ignore trailing slashes
    path = parsed.path
    if not path or path.endswith('/'):
        # Attempt to find query param 'id' if present
        query_id = urllib.parse.parse_qs(parsed.query).get('id')
        if query_id:
            image_id = query_id[0]
        else:
            raise ValueError("URL path does not contain an image identifier.")
    else:
        image_id = path.rsplit('/', 1)[-1]
        if not image_id:
            raise ValueError("Could not determine image identifier from path.")
    use_ssl = parsed.scheme.lower() == "https"
    return (image_id, parsed.netloc, use_ssl)<|return|>

