def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict mapping configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging

    # Helper to resolve environment variables in a serializable object
    def _resolve_env(value):
        if isinstance(value, str):
            # Replace ${VAR} with environment variable
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    results = {}
    error_records = []
    logger = logging.getLogger('load_configurations')

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
            try:
                cfg = json.loads(raw)
            except json.JSONDecodeError as e:
                # Create a LogRecord for JSON parsing error
                record = logging.makeRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'JSON parse error in {filename}: {e}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue  # skip to next file
            # Resolve environment variables if requested
            if resolve_env:
                cfg = _resolve_env(cfg)
            # Apply overrides if provided
            if overrides:
                for key, value in overrides.items():
                    cfg[key] = value
            results[filename] = cfg
        except FileNotFoundError as e:
            record = logging.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'File not found: {filename}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
        except Exception as e:
            # Catch any other error that might occur during file handling
            record = logging.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading {filename}: {e}',
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return results, error_records<|return|>

