    """Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import os
    import logging

    configs = {}
    error_records = []

    # Helper to resolve environment variables in strings
    def _resolve_env(value):
        if isinstance(value, str):
            # Expand ${VAR} or $VAR variables
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fp:
                # Determine parser by file extension
                if filename.lower().endswith(('.yaml', '.yml')):
                    try:
                        import yaml  # optional dependency
                    except ImportError:
                        raise RuntimeError("yaml module not available for YAML files")
                    data = yaml.safe_load(fp)
                else:
                    data = json.load(fp)

            # Basic validation: ensure a dict was loaded
            if not isinstance(data, dict):
                raise ValueError("Configuration content is not a dictionary")

            if resolve_env:
                data = _resolve_env(data)

            configs[filename] = data

        except Exception as e:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Error parsing configuration file '{filename}': {e}",
                args=(),
                exc_info=None
            )
            error_records.append(record)

    # Apply overrides if provided
    if overrides and isinstance(overrides, dict):
        for fname, config in configs.items():
            for key, value in overrides.items():
                config[key] = value

    return configs, error_records
<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
      - dict of configuration filename to corresponding parsed configuration,
      - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os
    configs = {}
    error_records = []

    def _resolve_env(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env(v) for v in obj]
        if isinstance(obj, str):
            # substitute env variable references like ${VAR} or $VAR
            import re
            pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')
            def repl(match):
                var = match.group(1) or match.group(2)
                return os.getenv(var, '')
            return pattern.sub(repl, obj)
        return obj

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                config = json.load(f)
            if resolve_env:
                config = _resolve_env(config)
            if overrides:
                # Apply overrides at the top level of the configuration.
                config.update(overrides)
            configs[fname] = config
        except Exception as e:
            record = logging.makeLogRecord({
                'name': __name__,
                'level': logging.ERROR,
                'pathname': fname,
                'lineno': 0,
                'msg': f'Error loading configuration {fname}: {e}',
                'args': (),
                'exc_info': None
            })
            error_records.append(record)

    return configs, error_records<|return|>

