@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
        If an explicit protocol version is provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol version is provided,
        all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # The registry of available protocol handlers is expected to be stored as a class attribute.
        # Each key is a tuple like (major, minor) and each value is the corresponding handler class.
        handlers = getattr(cls, "_protocol_handlers", {})
        if protocol_version is None:
            # Return a shallow copy so callers cannot modify the internal registry.
            return dict(handlers)

        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")

        # If the requested protocol is supported return it in a single-item dict, otherwise return empty dict.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}
<|return|>

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    processed = []
    for v in values:
        if isinstance(v, bytes):
            try:
                processed.append(v.decode("ascii"))
            except UnicodeDecodeError as exc:
                raise ValueError(f"Bookmark must be ASCII but got {v!r}") from exc
        elif isinstance(v, str):
            processed.append(v)
        else:
            raise TypeError(f"Bookmark value must be str or bytes, got {type(v)!r}")
    return cls(processed)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Define types considered as native sequences
    native_seqs = (list, tuple, str, bytes, bytearray, memoryview)
    if isinstance(seq, native_seqs):
        return seq, type(seq)

    # Try to build a list from seq with optional buffering
    derived = [] if bufsize is not None else None
    try:
        if bufsize is None:
            # Grab all elements
            return list(seq), list
        else:
            # Grab up to bufsize elements without importing itertools
            count = 0
            for item in seq:
                if count >= bufsize:
                    break
                derived.append(item)
                count += 1
            return derived, list
    except TypeError:
        # seq was not iterable; return as is with its type
        return seq, type(seq)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Types that are considered “already a sequence”.
    _known_seq_types = (list, tuple, set, frozenset, str)
    if isinstance(seq, _known_seq_types):
        return seq, type(seq)

    # For any other iterable, build a list (with optional buffer limit).
    if bufsize is None:
        seq_list = list(seq)
    else:
        seq_list = []
        count = 0
        for item in seq:
            seq_list.append(item)
            count += 1
            if count >= bufsize:
                break
    return seq_list, type(seq_list)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    from collections.abc import Sequence
    from itertools import islice

    # If a buffer size is requested, try to limit the amount of data gathered
    if bufsize is not None:
        try:
            # Use islice to lazily slice the iterable; convert to list
            seq = list(islice(seq, bufsize))
        except TypeError:
            # If seq is not sliceable or iterable, ignore the buffer request
            pass

    # If seq is already a sequence type, return it directly
    if isinstance(seq, Sequence) and not isinstance(seq, (bytes, bytearray)):
        sequence = seq
        seq_type = type(seq)
    else:
        # Convert non-sequence objects to a list, falling back if not iterable
        try:
            sequence = list(seq)
        except Exception:
            sequence = [seq]
        seq_type = type(seq)

    return sequence, seq_type<|return|>

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper: locate the underlying array of bin counts.
        _bins = None
        for name in ("data", "bins", "counts", "values"):
            if hasattr(self, name):
                _bins = getattr(self, name)
                break
        if _bins is None:
            raise AttributeError("Histogram object has no recognizable bin container.")
        # Helper: compute integral
        def _integral():
            try:
                return float(_bins.sum())
            except AttributeError:
                return float(sum(_bins))

        if other is None:
            # Return current scale
            if not hasattr(self, "_scale") or self._scale is None or recompute:
                self._scale = _integral()
            return self._scale
        else:
            # Rescale to the provided target scale
            try:
                target = float(other)
            except Exception as exc:
                raise TypeError(f"other must be convertible to float, got {other!r}") from exc
            # Compute current scale if necessary
            if not hasattr(self, "_scale") or self._scale is None:
                self._scale = _integral()
            if self._scale == 0:
                raise LenaValueError(
                    "Histograms with scale equal to zero can't be rescaled."
                )
            factor = target / self._scale
            # Apply factor to all bins
            try:
                _bins *= factor
            except TypeError:
                # Fallback to list comprehension if bins are plain python list
                for i in range(len(_bins)):
                    _bins[i] *= factor
            self._scale = target
            return self
<|return|>

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent
    use (unless explicitly asked to *recompute*). Note that after changing
    (filling) the histogram one must explicitly recompute the scale if it was
    computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Try to get cached scale
    if not recompute and hasattr(self, "_scale") and self._scale is not None:
        current_scale = self._scale
    else:
        # Compute scale from bin contents
        # Attempt to locate the container holding bin counts
        contents = getattr(self, "data", None)
        if contents is None:
            contents = getattr(self, "contents", None)
        if contents is None:
            contents = getattr(self, "_data", None)
        if contents is None:
            contents = getattr(self, "bins", None)
        if contents is None:
            raise ValueError("Histogram has no data to compute scale.")
        # Integral: sum of bin contents
        try:
            current_scale = sum(float(v) for v in contents)
        except Exception as exc:
            raise ValueError("Failed to compute scale: " + str(exc))
        # Cache the computed value
        setattr(self, "_scale", current_scale)

    # If other is None -> just return current scale
    if other is None:
        return current_scale

    # Rescale case
    try:
        target_scale = float(other)
    except Exception:
        raise TypeError("other must be a number representing the desired scale")

    if current_scale == 0.0:
        raise ValueError("Cannot rescale a histogram with zero scale")

    scale_factor = target_scale / current_scale

    # Fetch contents again for modification
    contents = getattr(self, "data", None)
    if contents is None:
        contents = getattr(self, "contents", None)
    if contents is None:
        contents = getattr(self, "_data", None)
    if contents is None:
        contents = getattr(self, "bins", None)
    if contents is None:
        raise ValueError("Histogram has no data to rescale")

    # Apply scaling to each bin
    for idx in range(len(contents)):
        try:
            contents[idx] = contents[idx] * scale_factor
        except Exception:
            # If contents are immutable or cannot be directly scaled, rebuild list
            contents = [c * scale_factor for c in contents]
            # Attempt to set back to original attribute
            for attr in ("data", "contents", "_data", "bins"):
                if hasattr(self, attr):
                    setattr(self, attr, contents)
                    break
            break

    # Update cached scale
    setattr(self, "_scale", target_scale)

    return None
<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide the interface *iface*.
    Returns ``True`` if the candidate satisfies the interface; otherwise
    returns ``False``.  When ``tentative`` is ``True`` the verification is
    more permissive and missing members are tolerated.
    """
    import inspect

    # Basic sanity checks
    if not inspect.isclass(iface):
        raise TypeError(f"Interface {iface!r} is not a class")
    if not inspect.isclass(candidate):
        return False

    # If candidate is already a subclass of iface, it's definitely acceptable
    if issubclass(candidate, iface):
        return True

    # Gather the abstract/method requirements from iface
    required = set()
    for name, value in getattr(iface, "__abstractmethods__", set()):
        required.add(name)
    # In case __abstractmethods__ is not available, look at public methods
    if not required:
        for name, value in vars(iface).items():
            if name.startswith("_"):
                continue
            if inspect.isroutine(value):
                required.add(name)

    # Verify that the candidate implements the required members
    for name in required:
        if not hasattr(candidate, name):
            if tentative:
                # Allow missing members when tentative is True
                continue
            return False
    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine metaclass from 1+ bases and optional explicit __metaclass__.
    """
    # Build list of candidate metaclasses.
    candidates = []
    if explicit_mc is not None:
        candidates.append(explicit_mc)
    candidates.extend(type(b) for b in bases)

    # If no bases, fall back to the default metaclass 'type'.
    if not candidates:
        return type

    # Resolve the best metaclass by finding a candidate that is a superclass
    # of all other candidates. Raise an error if there is no such candidate.
    best = None
    for cls in candidates:
        if best is None:
            best = cls
        elif issubclass(cls, best):
            best = cls
        elif not issubclass(best, cls):
            raise TypeError(f"metaclass conflict: {best} and {cls} are incompatible")
    return best<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases and explicit_mc is None:
        # Mimic Python's default
        return type
    # Gather all candidate metaclasses
    mcs = [type(b) for b in bases]
    if explicit_mc is not None:
        mcs.append(explicit_mc)
    unique_mcs = tuple(set(mcs))
    # If only one candidate, that's the answer
    if len(unique_mcs) == 1:
        return unique_mcs[0]
    # Find the most derived metaclass: subclass of all others
    most_derived = None
    for mc in unique_mcs:
        if all(issubclass(mc, other) for other in unique_mcs):
            if most_derived is not None:
                # Ambiguous conflict
                raise TypeError(
                    f"metaclass conflict: {most_derived} and {mc} are both "
                    f"most derived metaclasses and neither is a subclass of the other"
                )
            most_derived = mc
    if most_derived is None:
        raise TypeError(
            "metaclass conflict: no metaclass found that is a subclass "
            "of all of the metaclasses"
        )
    return most_derived<|return|>

