def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    import datetime
    import re

    class ParserError(Exception):
        pass

    class tzoffset(datetime.tzinfo):
        def __init__(self, name, offset):
            self.name = name
            self.offset = datetime.timedelta(seconds=offset)

        def utcoffset(self, dt):
            return self.offset

        def tzname(self, dt):
            return self.name

        def dst(self, dt):
            return datetime.timedelta(0)

    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")

    # Simple regex to parse common ISO-like formats and optional timezone.
    pattern = re.compile(r"""
        ^\s*
        (?P<year>\d{4})
        [/-.]
        (?P<month>\d{1,2})
        [/-.]
        (?P<day>\d{1,2})
        (?:[ T]
            (?P<hour>\d{1,2})
            :
            (?P<minute>\d{1,2})
            (?:
                :
                (?P<second>\d{1,2})
            )?
        )?
        (?:\s*
            (?P<tzsign>[+-])
            (?P<tzhour>\d{2})
            :?(?P<tzmin>\d{2})
        )
        \s*
        (?P<tzname>\w+)?\s*$
    """, re.VERBOSE | re.IGNORECASE)

    m = pattern.match(timestr)
    if not m:
        raise ParserError(f"Cannot parse date: {timestr!r}")

    parts = m.groupdict()

    # Determine base components, using default where necessary.
    def get_component(key, default_val, cast=int):
        val = parts.get(key)
        if val is None:
            if default is not None and hasattr(default, key):
                return getattr(default, key)
            else:
                return default_val
        return cast(val)

    year = get_component('year', 0)
    month = get_component('month', 0)
    day = get_component('day', 0)
    hour = get_component('hour', get_component('hour', 0, int), int) or 0
    minute = get_component('minute', get_component('minute', 0, int), int) or 0
    second = get_component('second', 0, int) or 0

    tz_info = None
    if ignoretz:
        tz_info = None
    else:
        # First check explicit tzname mapping
        tzname = parts.get('tzname')
        if tzname and tzinfos:
            tz_val = tzinfos.get(tzname)
            if tz_val is not None:
                if isinstance(tz_val, datetime.tzinfo):
                    tz_info = tz_val
                elif isinstance(tz_val, (int, float)):
                    tz_info = tzoffset(tzname, tz_val)
                else:
                    raise ParserError(f"Unsupported tzinfo value for {tzname}")

        # If tzinfo still None, try parsing offset
        if tz_info is None and parts.get('tzsign'):
            sign = 1 if parts['tzsign'] == '+' else -1
            offset_hours = int(parts['tzhour'])
            offset_minutes = int(parts['tzmin'])
            offset_seconds = sign * ((offset_hours * 3600) + (offset_minutes * 60))
            tz_info = tzoffset("offset", offset_seconds)

    try:
        dt = datetime.datetime(year, month, day, hour, minute, second, tzinfo=tz_info)
    except Exception as exc:
        raise ParserError(f"Error constructing datetime: {exc}") from exc

    return dt
<|return|>

def identify_request(request):
    """
    Try to identify whether this is a Diaspora request.

    The function first checks for a public message, then a private message,
    and finally looks for a legacy payload that contains a marker
    identifying the request as originating from Diaspora.

    Parameters
    ----------
    request : Any
        The request object to examine.  It may be a dictionary or an
        object with a ``__dict__`` attribute containing request data.

    Returns
    -------
    bool
        ``True`` if the request appears to originate from Diaspora;
        ``False`` otherwise.
    """
    # Normalise the request into a dictionary if possible
    try:
        if isinstance(request, dict):
            data = request
        else:
            data = getattr(request, "__dict__", {})
    except Exception:
        return False

    # Helper: check if a string contains the keyword "diaspora"
    def has_diaspora_marker(text: str) -> bool:
        return "diaspora" in text.lower()

    # 1. Look for a public message
    if data.get("msg_type") == "public" or data.get("type") == "public":
        if has_diaspora_marker(str(data)):
            return True

    # 2. Look for a private message
    if data.get("msg_type") == "private" or data.get("type") == "private":
        if has_diaspora_marker(str(data)):
            return True

    # 3. Legacy payload check
    payload = data.get("payload")
    if isinstance(payload, dict):
        # A legacy payload may be identified by a "platform" or
        # similar key that explicitly names Diaspora.
        platform = payload.get("platform") or payload.get("source")
        if platform and has_diaspora_marker(platform):
            return True
        # Sometimes the presence of a specific legacy key is enough
        if any(key.lower() == "diaspora" for key in payload):
            return True

    # If none of the checks succeed, assume it is not a Diaspora request
    return False<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for public request
    try:
        if hasattr(request, "is_public") and request.is_public:
            return True
    except Exception:
        pass

    # Check for private request
    try:
        if hasattr(request, "is_private") and request.is_private:
            return True
    except Exception:
        pass

    # Check for legacy payload
    try:
        payload = getattr(request, "payload", {})
        if isinstance(payload, dict) and "legacy" in payload:
            return True
    except Exception:
        pass

    return False<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Handle mapping-like requests
    if isinstance(request, dict):
        if 'public_message' in request:
            return True
        if 'private_message' in request:
            return True
        if 'legacy_payload' in request:
            return True
        return False

    # Handle object requests
    if hasattr(request, 'public_message'):
        return True
    if hasattr(request, 'private_message'):
        return True
    if hasattr(request, 'legacy_payload'):
        return True

    # Fallback: look for known keys in generic attribute access
    for key in ('public_message', 'private_message', 'legacy_payload'):
        if getattr(request, key, None) is not None:
            return True

    return False<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for Diaspora specific headers that may indicate a Diaspora request
    if request.headers.get('X-Diaspora-Request') == 'true':
