    """
    # The D* nodes expect an ISO‑8601 string in UTC with the trailing "Z".
    # If the datetime is timezone‑aware we first convert it to UTC,
    # otherwise we assume it is already in UTC.
    if dt.tzinfo is not None:
        try:
            # Convert to UTC
            dt_utc = dt.astimezone(
                type(dt.tzinfo).utc
            )
        except AttributeError:
            # Fallback if the tzinfo does not expose 'utc'
            dt_utc = dt.astimezone()
    else:
        dt_utc = dt
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")<|return|>

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    # Find all fenced code block spans (including the fence markers)
    code_spans = [(m.start(), m.end()) for m in re.finditer(r'```.*?```', text, flags=re.S)]
    tags: Set[str] = set()
    tag_re = re.compile(r'#(\w+)')

    def in_code(pos: int) -> bool:
        for start, end in code_spans:
            if start <= pos < end:
                return True
        return False

    def repl(match: re.Match) -> str:
        pos = match.start()
        # Skip tags that are inside code blocks
        if in_code(pos):
            return match.group(0)
        tag_word = match.group(1)
        tags.add(tag_word)
        if replacer:
            # Replace only the tag word, keep the leading '#'
            return '#' + replacer(tag_word)
        return match.group(0)

    new_text = tag_re.sub(repl, text)
    return tags, new_text<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    from urllib.request import Request, urlopen
    from urllib.error import HTTPError, URLError

    try:
        req = Request(url, method="HEAD")
        with urlopen(req) as resp:
            return resp.headers.get("Content-Type")
    except (HTTPError, URLError):
        return None<|return|>

