    except json.JSONDecodeError:
        pass

    # Try XRD (old format)
    try:
        root = ET.fromstring(document)
        # Helper to get local tag name without namespace
        get_local = lambda tag: tag.split('}')[-1]

        subject = None
        aliases = []
        links = []

        for elem in root.iter():
            local = get_local(elem.tag)
            if local == 'Subject' and subject is None:
                subject = elem.text
            elif local == 'Alias':
                if elem.text is not None:
                    aliases.append(elem.text)
            elif local == 'Link':
                href = elem.get('href')
                rel = elem.get('rel')
                type_val = elem.get('type')
                if href:
                    links.append({'rel': rel, 'href': href, 'type': type_val})

        return {'subject': subject, 'aliases': aliases, 'links': links}
