    resource = f"acct:{user}@{domain}"
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"
    # Try HTTPS first, fall back to HTTP if necessary
    urls = [url]
    if url.startswith("https"):
        urls.append(url.replace("https", "http", 1))
    elif url.startswith("http"):
        urls.append(url.replace("http", "https", 1))
    import urllib.request, urllib.error, json
    for url in urls:
        try:
            req = urllib.request.Request(url, headers={'Accept': 'application/json'})
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status != 200:
