    :arg handle: Remote handle to retrieve (e.g., 'alice@example.com')
    :returns: dict representation of the JSON payload
    """
    # Basic validation of the handle
    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError(f"'{handle}' is not a valid Diaspora handle")

    # Construct the webfinger URL
    protocol = "https://"
    resource = f"acct:{handle}"
    base_url = handle.split("@", 1)[1]
    url = f"{protocol}{base_url}/.well-known/webfinger?resource={resource}"

    import json
    import ssl
    import urllib.request
    import urllib.error

    # Create a Request object so we can set a custom Accept header
    req = urllib.request.Request(url, headers={"Accept": "application/json"})

    # Use an unverified context for simplicity (real code should verify certs)
    ctx = ssl._create_unverified_context()

    try:
        with urllib.request.urlopen(req, context=ctx) as resp:
            data = resp.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        # If HTTPS fails and we receive a 404 or other error, try HTTP as a fallback
        if e.code == 404 and url.startswith(protocol):
            http_url = url.replace(protocol, "http://", 1)
            req_http = urllib.request.Request(
                http_url, headers={"Accept": "application/json"}
            )
            try:
                with urllib.request.urlopen(req_http, context=ctx) as resp:
                    data = resp.read().decode("utf-8")
            except Exception as ex:
                raise RuntimeError(f"Failed to retrieve webfinger via HTTP: {ex}") from ex
        else:
            raise RuntimeError(f"HTTP error retrieving webfinger: {e}") from e
    except Exception as exc:
        raise RuntimeError(f"Error retrieving webfinger: {exc}") from exc

    try:
        return json.loads(data)
    except json.JSONDecodeError as ned:
        raise RuntimeError(f"Failed to parse JSON from webfinger response: {ned}") from ned<|return|>

