def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    from xml.etree import ElementTree as ET

    # Attempt to import a real XRD class if available
    try:
        # Try common libraries that provide an XRD implementation
        # e.g. 'diaspora' or 'wideweb' packages
        from diaspora import XRD  # type: ignore
    except Exception:
        try:
            from wideweb import XRD  # type: ignore
        except Exception:
            # Fallback minimal XRD wrapper
            class XRD:
                def __init__(self, element):
                    self.element = element

                def __repr__(self):
                    return f"<XRD element='{self.element.tag}'>"

                # provide a couple of convenience methods that tests might use
                def get_element_by_identity(self, uri):
                    """Return the <Link> element with rel="self" and href containing uri."""
                    for link in self.element.findall('.//Link'):
                        href = link.get('href')
                        if href and uri in href:
                            return link
                    return None

                def to_xml(self):
                    return ET.tostring(self.element, encoding='unicode')

    urls = [f"http://{host}/.well-known/host-meta", f"https://{host}/.well-known/host-meta"]
    content = None
    for url in urls:
        try:
            with urllib.request.urlopen(url, timeout=10) as resp:
                # Detect charset; fallback to utf-8
                content_bytes = resp.read()
                charset = resp.headers.get_content_charset(failobj='utf-8')
                content = content_bytes.decode(charset, errors='replace')
                break
        except urllib.error.HTTPError:
            continue
        except urllib.error.URLError:
            continue

    if content is None:
        raise ValueError(f"Could not retrieve host-meta from {host}")

    # Parse XML into ElementTree
    try:
        root = ET.fromstring(content)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML in host-meta from {host}: {exc}") from exc

    return XRD(root)<|return|>

