def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type."""
    from pathlib import Path
    result = []

    # Normalize settings_dirs to a list of Path objects
    if isinstance(settings_dirs, (str, Path)):
        dirs = [Path(settings_dirs)]
    else:
        dirs = [Path(d) for d in settings_dirs]

    # Function to get all files matching spec_option
    def collect_files(base_dir, pattern):
        try:
            # If the pattern contains glob wildcards, use rglob for recursive search
            if any(char in pattern for char in "*?["):
                for fp in base_dir.rglob(pattern):
                    if fp.is_file():
                        yield fp.resolve()
            else:
                # Assume pattern is an extension like ".ini" or a literal file name
                for fp in base_dir.glob(f"*{pattern}"):
                    if fp.is_file():
                        yield fp.resolve()
        except Exception:
            # In case of any globbing error, fallback to ignoring this directory
            return

    for d in dirs:
        if not d.is_dir():
            continue
        for fp in collect_files(d, spec_option):
            result.append(str(fp))

    return sorted(result)<|return|>

