        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No YAML file specified.")
        try:
            import yaml
            import os
        except Exception as e:
            raise IRValidatorException(f"Failed to import dependencies: {e}")

        if not os.path.exists(yaml_file):
            raise IRValidatorException(f"YAML file '{yaml_file}' does not exist.")
        try:
            with open(yaml_file, "r") as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise IRValidatorException(f"Error reading YAML file: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a mapping at the top level.")

        # Define the required top‑level fields for this project
        required_fields = ["name", "spec", "metadata"]
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")

        return data<|return|>

