            )

        required_fields = getattr(cls, "REQUIRED_YAML_FIELDS", None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required top‑level fields in '{yaml_file}': {', '.join(missing)}"
                )

        return data<|return|>

