    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import yaml

    if yaml_file is None:
        raise ValueError("yaml_file must be provided")
    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except Exception as exc:
        raise IRValidatorException(f"Failed to load YAML file: {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException("YAML root must be a mapping")

    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(
            f"Missing required fields in YAML: {', '.join(missing)}"
        )
    return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    The spec may contain an ``include_groups`` key whose value is either a
    single group name or a list of group names.  Groups are looked up in
    ``self._groups`` – a mapping of group names to dicts – and merged into
    ``parser_dict``.  The merge is deep and respects list concatenation.
    """
    def _merge(target, source):
        for key, value in source.items():
            if key in target:
                # Preserve lists
                if isinstance(target[key], list) and isinstance(value, list):
                    target[key].extend(value)
                # Merge nested dicts
                elif isinstance(target[key], dict) and isinstance(value, dict):
                    _merge(target[key], value)
                else:
                    target[key] = value
            else:
                target[key] = value

    if not parser_dict:
        return parser_dict

    # Handle any top‑level ``include_groups`` directive
    include_key = "include_groups"
    if include_key in parser_dict:
        groups = parser_dict.pop(include_key)
        if isinstance(groups, str):
            groups = [groups]
        if not isinstance(groups, list):
            groups = [groups]
        for name in groups:
            group_def = dict(self._groups.get(name, {}))
            # Recursively resolve includes inside the group definition
            group_def = self._include_groups(group_def)
            _merge(parser_dict, group_def)

    # Recursively resolve nested dicts
    for k, v in list(parser_dict.items()):
        if isinstance(v, dict):
            parser_dict[k] = self._include_groups(v)

    return parser_dict<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Start with defaults defined in the spec's arguments section
    defaults = {}
    if hasattr(self, "spec"):
        for arg in self.spec.get("arguments", []):
            name = arg.get("name") or arg.get("id") or arg.get("key")
            if name:
                defaults[name] = arg.get("default")
    # Override or add defaults from any instance attributes that are not private and not None
    for attr, value in vars(self).items():
        if not attr.startswith("_") and value is not None:
            defaults.setdefault(attr, value)
    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Attempt to extract defaults from a callable spec, if present
    spec = getattr(self, 'spec', None)
    if spec and callable(spec):
        import inspect
        try:
            sig = inspect.signature(spec)
            for name, param in sig.parameters.items():
                if param.default is not inspect.Parameter.empty:
                    defaults[name] = param.default
        except Exception:
            # If signature inspection fails, ignore
            pass
    # Merge in any defaults provided via a `params` attribute
    if hasattr(self, 'params'):
        for name, value in getattr(self, 'params').items():
            defaults.setdefault(name, value)
    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Retrieve default values defined in the spec
    spec_args = getattr(self, "spec", {}).get("arguments", {})
    for arg_name, arg_def in spec_args.items():
        if isinstance(arg_def, dict) and "default" in arg_def:
            defaults[arg_name] = arg_def["default"]
        else:
            # If the spec entry is not a dict, treat it as the default value
            defaults[arg_name] = arg_def
    # Apply any overrides that have been supplied (e.g., from init parameters)
    overrides = getattr(self, "overrides", {})
    defaults.update(overrides)
    return defaults<|return|>

