def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        subparsers = self.parser._subparsers
    except AttributeError:
        return []

    for action in getattr(subparsers, "_actions", []):
        # SubParsersAction objects have a 'choices' attribute that maps command names to subparsers
        if hasattr(action, "choices"):
            subparser = action.choices.get(command_name)
            if subparser:
                option_specs = []
                for sub_action in getattr(subparser, "_actions", []):
                    if hasattr(sub_action, "option_strings"):
                        option_specs.extend(sub_action.option_strings)
                return option_specs
    return []<|return|>

