        return self._options[command_name][argument_name]
    except KeyError:
        return None<|return|>

def get_option_spec(self, command_name, argument_name):
        """Gets the specification for the specified option name. """
        # Ensure the command exists
        if command_name not in self.commands:
            raise KeyError(f"Command '{command_name}' not found.")
        command_info = self.commands[command_name]

        # Some implementations may store options under a different key
        options = command_info.get("options") or getattr(command_info, "options", None)

        if not options:
            raise KeyError(f"No options defined for command '{command_name}'.")
        if argument_name not in options:
            raise KeyError(
                f"Option '{argument_name}' not found in command '{command_name}'."
            )

        return options[argument_name]<|return|>

