def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    # Support both dicts and objects such as argparse.Namespace
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = vars(args).items()
        except Exception:
            # If vars() fails, fall back to attribute iteration
            items = [
                (attr, getattr(args, attr))
                for attr in dir(args)
                if not attr.startswith('_')
            ]
    for key, value in items:
        if value is None:
            silent.append(key)
    return silent}<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required argument names; can be stored in
    # either `self.required` or `self.requires` for backward compatibility.
    required = getattr(self, "required", None)
    if required is None:
        required = getattr(self, "requires", None)

    # If no required arguments are defined, nothing to validate.
    if not required:
        return

    # Normalise to a list (handles tuples, sets, etc.).
    if isinstance(required, (set, tuple)):
        required = list(required)
    elif not isinstance(required, list):
        required = [required]

    # Find which required arguments are missing from the provided `args`.
    missing = [name for name in required if name not in args]

    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required arguments: {missing_str}")<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required argument names.
    required = getattr(self, "required_args", None)
    if required is None:
        # Fallback to common attribute names if not explicitly set.
        required = getattr(self, "requires", [])
    if not required:
        # Nothing to validate.
        return True

    missing = []
    for key in required:
        if isinstance(args, dict):
            # Dictionary access: key must exist and not be None.
            if key not in args or args[key] is None:
                missing.append(key)
        else:
            # Assume args behaves like argparse.Namespace (attribute access).
            if not hasattr(args, key) or getattr(args, key) is None:
                missing.append(key)

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True<|return|>

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided."""
        # Ensure args is a mapping; if not, treat it as empty
        if args is None:
            args = {}
        # Get the list or set of required argument names
        required = getattr(self, 'required_args', set())
        if isinstance(required, (list, tuple, set)):
            required_set = set(required)
        else:
            required_set = set(required)
        # Find any missing required arguments
        missing = [name for name in required_set if name not in args]
        if missing:
            raise ValueError(f"Missing required arguments: {', '.join(missing)}")<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the set of provided argument names
    if isinstance(args, dict):
        provided = set(args.keys())
    else:
        try:
            provided = set(args)
        except TypeError:
            raise TypeError("args must be a dict or an iterable of argument names")
    # Retrieve the set of required argument names; default to empty set if not defined
    required = getattr(self, "required_args", set())
    # Find any missing required arguments
    missing = [name for name in required if name not in provided]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")
    return True<|return|>

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditional_required = []
        for opt in options_spec:
            name = opt.get("name")
            if not name:
                continue
            required_when = opt.get("required_when")
            if required_when is None:
                continue

            # If ``required_when`` is a callable, evaluate it with ``args``.
            if callable(required_when):
                try:
                    condition_met = required_when(args)
                except Exception:
                    condition_met = False
            # If it's a boolean, take it as the condition.
            elif isinstance(required_when, bool):
                condition_met = required_when
            # If it's a string, treat it as a flag name that must be truthy.
            elif isinstance(required_when, str):
                condition_met = bool(args.get(required_when))
            else:
                # Unsupported type; skip
                condition_met = False

            if condition_met:
                conditional_required.append(name)
        return conditional_required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Retrieve 'required_when' and 'name' from dict or attribute
        required_when = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        if not required_when:
            continue
        try:
            # Prepare a safe evaluation context
            local_ctx = {'command_name': command_name, 'args': args}
            if eval(required_when, {}, local_ctx):
                opt_name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
                if opt_name:
                    required.append(opt_name)
        except Exception:
            # If condition evaluation fails, simply ignore this option
            continue
    return required
<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditional_required = []

        for opt in options_spec:
            # Determine option name
            if isinstance(opt, dict):
                opt_name = opt.get('name')
                required_when = opt.get('required_when')
            elif isinstance(opt, (list, tuple)):
                # assume first element is name
                opt_name = opt[0] if opt else None
                required_when = opt[2] if len(opt) > 2 else None
            else:
                continue

            if opt_name is None:
                continue

            if required_when is None:
                continue

            # Evaluate the condition
            condition_met = False
            if callable(required_when):
                try:
                    condition_met = bool(required_when(args))
                except Exception:
                    condition_met = False
            elif isinstance(required_when, dict):
                # All key-value pairs must match in args
                condition_met = all(args.get(k) == v for k, v in required_when.items())
            elif isinstance(required_when, list):
                # List of conditions: all must be satisfied
                try:
                    condition_met = all(bool(cond(args)) for cond in required_when if callable(cond))
                except Exception:
                    condition_met = False
            else:
                # Unsupported condition type; ignore
                condition_met = False

            if condition_met:
                conditional_required.append(opt_name)

        return conditional_required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        cond = opt.get('required_when')
        if cond:
            # If the condition is a callable, evaluate it with the args
            if callable(cond):
                try:
                    if cond(args):
                        required.append(opt['name'])
                except Exception:
                    # If the callable raises an exception treat it as unmet
                    continue
            else:
                # Handle condition specified as a string or a sequence of strings
                # If it's a sequence, all specified keys must have truthy values
                if isinstance(cond, (list, tuple, set)):
                    if all(args.get(c) for c in cond):
                        required.append(opt['name'])
                else:
                    # Single key condition: pass if truthy value present
                    if args.get(cond):
                        required.append(opt['name'])
    return required<|return|>

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.
        :param args: The received arguments.
        """
        # Retrieve expected maximum lengths for arguments, if defined
        max_lengths = getattr(self, 'max_lengths', {})
        for key, value in args.items():
            # Only validate if a maximum length is specified for this key
            if key in max_lengths:
                max_len = max_lengths[key]
                try:
                    current_len = len(value)
                except TypeError:
                    # Skip non‑lengthable values
                    continue
                if current_len > max_len:
                    raise ValueError(
                        f"Argument '{key}' exceeds maximum length {max_len} "
                        f"(got {current_len})."
                    )
        # No return value needed; validation passes silently if no errors.<|return|>

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises ValueError: If any argument exceeds its maximum allowed length.
    """
    # A mapping from argument names to maximum allowed lengths.
    max_lengths = getattr(self, 'max_lengths', {})

    # Accept a dict of arguments or an iterable of key-value pairs.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = iter(args)
        except TypeError:
            raise TypeError("args must be a dict or an iterable of (key, value) pairs")

    for key, value in items:
        # Skip arguments that have no defined max length.
        max_len = max_lengths.get(key)
        if max_len is None:
            continue

        # Determine the length of the value if possible.
        try:
            val_len = len(value)
        except Exception:
            # If the value does not support len(), ignore it.
            continue

        if val_len > max_len:
            raise ValueError(
                f"Argument '{key}' is too long: {val_len} characters (max {max_len})"
            )<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for name, value in args.items():
        if isinstance(value, (str, list, tuple, set, dict)):
            # Determine the maximum allowed length for this argument.
            max_len = getattr(self, f"{name.upper()}_MAX_LENGTH", 100)
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{name}' exceeds maximum length of {max_len} "
                    f"characters (got {len(value)})."
                )<|return|>

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        Raises:
            ValueError: If any argument exceeds its specified maximum length.
        """
        max_lengths = getattr(self, "max_lengths", {})
        default_str = getattr(self, "default_str_length", 255)
        default_iterable = getattr(self, "default_iterable_length", 255)

        for key, value in args.items():
            # Determine the allowed maximum
            max_len = max_lengths.get(key)
            if max_len is None:
                # fall back to type‑based default
                if isinstance(value, (str, bytes)):
                    max_len = default_str
                else:
                    max_len = default_iterable

            if max_len is None:
                # nothing to check
                continue

            try:
                length = len(value)
            except Exception:
                # Not a sized object; skip validation
                continue

            if length > max_len:
                raise ValueError(
                    f"Argument '{key}' has length {length} which exceeds the allowed maximum of {max_len}."
                )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices."""
    # The class is expected to provide a mapping `self.choices`
    # where each key is an argument name and the value is an
    # iterable of allowed values. If this attribute is missing,
    # we simply skip validation.
    choices_map = getattr(self, "choices", {})
    for arg_name, arg_value in args.items():
        if arg_name not in choices_map:
            # No defined choices for this argument – nothing to validate
            continue
        allowed = choices_map.get(arg_name)
        # If the allowed values are specified as a dict (mapping to a
        # sub‑list of allowed values), take the values part.
        if isinstance(allowed, dict):
            allowed = allowed.values()
        # Skip validation if no allowed values were provided
        if not allowed:
            continue
        # Allow None for optional arguments – treat as valid
        if arg_value is None:
            continue
        # For iterable arguments (e.g., list of choices) we validate
        # each element; otherwise we just check the single value.
        if isinstance(arg_value, (list, tuple, set)):
            if not all(v in allowed for v in arg_value):
                raise ValueError(
                    f"Argument '{arg_name}' has invalid value(s) {arg_value!r} – "
                    f"allowed values are {tuple(allowed)}."
                )
        else:
            if arg_value not in allowed:
                raise ValueError(
                    f"Argument '{arg_name}' has value {arg_value!r} which is not among "
                    f"the allowed values {tuple(allowed)}."
                )
    return True<|return|>

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Retrieve the mapping of argument names to their allowed choices.
        # The mapping is expected to be stored in `self.choices` as a dict
        # where keys are argument names and values are iterables of allowed values.
        choices_def = getattr(self, 'choices', {})
        for arg_name, arg_value in args.items():
            if arg_name in choices_def:
                allowed = choices_def[arg_name]
                # Handle scalar and iterable values uniformly.
                vals = arg_value if isinstance(arg_value, (list, tuple, set)) else (arg_value,)
                for v in vals:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{arg_name}': {v}. "
                            f"Allowed values are: {list(allowed)}."
                        )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Normalize args to a dict if it's a Namespace or other object
    if not isinstance(args, dict):
        args = vars(args)

    # Retrieve the argument definitions (assumed to be stored in self.arg_defs)
    arg_defs = getattr(self, "arg_defs", {})

    for arg_name, value in args.items():
        # Get the definition for this argument, if any
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            continue

        # Check if the argument has defined choices
        choices = arg_def.get("choices")
        if not choices:
            continue

        # Support for arguments that accept multiple values
        if isinstance(value, (list, tuple)):
            # Find all invalid values in the list
            invalids = [v for v in value if v not in choices]
            if invalids:
                raise ValueError(
                    f"Argument '{arg_name}' has invalid value(s) {invalids}. Expected one of {choices}."
                )
        else:
            # Single value check
            if value not in choices:
                raise ValueError(
                    f"Argument '{arg_name}' has invalid value {value}. Expected one of {choices}."
                )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments expected as a mapping of argument names to
