def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity flags
    if verbose:
        if not isinstance(verbose, int):
            raise ValueError("`verbose` must be an integer")
        # add '-vvvv' style flag
        cmd.append("-" + "v" * verbose)

    # Add custom ansible-playbook arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("`ansible_args` must be a dictionary")
        for key, value in ansible_args.items():
            if not key.startswith("--"):
                flag = f"--{key}"
            else:
                flag = key
            if value is None:
                cmd.append(flag)
            else:
                # When key accepts a value, ensure it's stringified
                cmd.extend([flag, str(value)])

    # Add extra-vars
    if extra_vars:
        import json
        try:
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError("`extra_vars` must be JSON serializable") from exc
        cmd.extend(["--extra-vars", json_str])

    # Execute the command
    import subprocess
    try:
        result = subprocess.run(
            cmd,
            text=True,
            capture_output=True,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        # Log the error to the workspace or plugin if available
        if ir_workspace and hasattr(ir_workspace, "log"):
            try:
                ir_workspace.log.write(exc.stdout)
                ir_workspace.log.error.write(exc.stderr)
            except Exception:
                pass
        if ir_plugin and hasattr(ir_plugin, "log"):
            try:
                ir_plugin.log.write(exc.stdout)
                ir_plugin.log.error.write(exc.stderr)
            except Exception:
                pass
        # Re-raise to indicate failure
        raise

    # Return the CompletedProcess for further inspection if needed
    return result
