def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess, json, sys

    cmd = ['ansible-playbook', str(playbook_path)]

    # Handle verbosity
    if verbose:
        if isinstance(verbose, int):
            # Add up to 4 '-v' flags
            flag_count = min(max(verbose, 0), 4)
            cmd.extend(['-v'] * flag_count)
        elif isinstance(verbose, str):
            if verbose.startswith('-'):
                cmd.append(verbose)

    # Handle custom ansible arguments
    if ansible_args:
        for k, v in ansible_args.items():
            key = str(k)
            # Ensure key starts with '-' or '--'
            if not key.startswith('-'):
                key = '--' + key
            if v is None:
                cmd.append(key)
            else:
                # Convert complex objects to JSON
                if isinstance(v, (dict, list)):
                    val = json.dumps(v)
                else:
                    val = str(v)
                cmd.extend([key, val])

    # Handle extra_vars
    if extra_vars:
        cmd.extend(['--extra-vars', json.dumps(extra_vars)])

    # Execute the command
    result = subprocess.run(cmd, capture_output=True, text=True)

    # Log output – use ir_plugin if available, else fallback to stdout/stderr
    if hasattr(ir_plugin, 'log'):
        ir_plugin.log(result.stdout, level='info')
        if result.stderr:
            ir_plugin.log(result.stderr, level='error')
    else:
        sys.stdout.write(result.stdout)
        if result.stderr:
            sys.stderr.write(result.stderr)

    return result
