    else:
        # Simple YAML loader fallback using json for based lines
        # This is a very naive parser that only handles plain key: value pairs and nested dictionaries.
        # For complex YAML, a proper parser should be used.
        def parse_yaml(lines, indent=0):
            result = {}
            current_key = None
            current_dict = result
            for line in lines:
                stripped = line.strip()
                if not stripped or stripped.startswith("#"):
                    continue
                indent_level = len(line) - len(line.lstrip(" "))
                key, value = stripped.split(":", 1)
                key = key.strip()
                value = value.strip()
                if value == "":
                    # nested dict
                    sub_dict = {}
                    current_dict[key] = sub_dict
                    current_dict = sub_dict
                else:
                    # simple value
                    current_dict[key] = value
            return result

        with open(spec_file, "r", encoding="utf-8") as f:
            spec = parse_yaml(f.readlines())

    # Flatten the dictionary
    flat = {}

    def _flatten(d, parent_key=""):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
