def strip_root(path, root):
    import os
    # Normalize both path and root to use OS specific separators
    path_norm = os.path.normpath(path)
    root_norm = os.path.normpath(root)

    # For case-insensitive file systems (Windows) perform case-insensitive comparison
    if os.name == "nt":
        path_cmp = path_norm.lower()
        root_cmp = root_norm.lower()
    else:
        path_cmp = path_norm
        root_cmp = root_norm

    # If root is just the filesystem root "/", strip only the leading separator(s)
    if root_cmp == os.sep:
        if path_cmp.startswith(os.sep):
            return path_norm.lstrip(os.sep)
        raise ValueError(f"Path '{path_norm}' does not start with root '{root_norm}'.")

    # Exact match: path is identical to root
    if path_cmp == root_cmp:
        return ""

    # If path starts with root followed by a separator (ensuring a component match)
    if path_cmp.startswith(root_cmp + os.sep):
        # Remove the root and the following separator
        return path_norm[len(root_norm) + 1 :]

    # The path does not start with the root
    raise ValueError(f"Path '{path_norm}' does not start with root '{root_norm}'.")<|return|>
